"""sections_results4.tex: format-parser and sequence-property validations (proteinprops, restriction, stockholm, gff) from committed JSON."""
import json
B='../benchmarks/'
esc=lambda s:str(s).replace('_','\\_').replace('&','\\&').replace('%','\\%').replace('#','\\#')
pp=json.load(open(B+'sweep_proteinprops_restriction.json')); sto=json.load(open(B+'sweep_stockholm_biopython.json')); gf=json.load(open(B+'sweep_gff_gffutils.json'))
o=['\\section{Sequence properties, restriction digests and file formats}']
o.append(f"This section checks four bio/ libraries against {esc(pp['reference'])} and gffutils. Three pass exactly. One, the restriction-site finder, had a real bug that we fixed.")
o.append('\\subsection{Protein physicochemical properties}')
o.append(f"On {pp['n_proteins']} UniProtKB reviewed human proteins ({esc(pp['proteins'])}), every property matches ProtParam (Table~\\ref{{tab:pp}}).")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{lrrrr}\\hline property & $n$ & within tol. & max abs diff & Pearson\\\\\\hline')
for k,v in pp['proteinprops'].items(): o.append(f"{esc(k)} & {v['n']} & {v['n_within_tol']} ({esc(v['tol'])}) & {v['max_abs_diff']:.2g} & {v['pearson']:.10f}\\\\")
o.append('\\hline\\end{tabular}\\caption{bio.proteinprops vs Biopython ProtParam (benchmarks/sweep\\_proteinprops\\_restriction.json).}\\label{tab:pp}\\end{table}')
o.append('\\paragraph{(F36) Average molecular weight.} $M=\\sum_a n_a m_a-(L-1)\\,m_{\\mathrm{H_2O}}$, with $m_a$ the average residue mass (free amino acid) and one water lost per peptide bond.')
o.append('\\paragraph{(F37) Net charge.} $Z(\\mathrm{pH})=\\sum_{i\\in +}\\frac{n_i}{1+10^{\\mathrm{pH}-pK_i}}-\\sum_{j\\in -}\\frac{n_j}{1+10^{pK_j-\\mathrm{pH}}}$ (Henderson--Hasselbalch per ionisable group, termini included).')
o.append('\\paragraph{(F38) Isoelectric point.} $\\mathrm{pI}$ is the root of $Z(\\mathrm{pH})=0$; $Z$ is strictly decreasing in pH, so bisection on $[0,14]$ converges, and the residual $6\\times10^{-5}$ difference is the bisection tolerance.')
o.append('\\paragraph{(F39) Instability index.} $II=\\frac{10}{L}\\sum_{i=1}^{L-1}\\mathrm{DIWV}(x_i,x_{i+1})$ (Guruprasad 1990), and GRAVY $=\\frac1L\\sum_i h_{KD}(x_i)$ (Kyte--Doolittle).')
o.append('\\paragraph{(F40) Extinction coefficient at 280 nm.} $\\varepsilon=5500\\,n_W+1490\\,n_Y+125\\,n_{\\mathrm{cystine}}$ M$^{-1}$cm$^{-1}$, with $n_{\\mathrm{cystine}}=\\lfloor n_C/2\\rfloor$ in the oxidised form and $0$ when reduced.')
o.append('\\subsection{Restriction sites: a bug in degenerate recognition sequences}')
b=pp['restriction_before_fix']; r=pp['restriction']
o.append(f"We digested pBR322 (J01749.1, circular, {r['J01749.1']['length']:,} bp) and phage lambda (NC\\_001416.1, linear, {r['NC_001416.1']['length']:,} bp) with all {r['J01749.1']['n_enzymes']} enzymes and compared cut positions with Biopython Restriction. Before the fix (sugarcode-ai {b['sugarcode_commit']}), {b['J01749.1']['agree']} and {b['NC_001416.1']['agree']} enzymes agreed. Two causes explained the disagreements. First, the reverse-strand pattern for a non-palindromic-looking site was built with a plain DNA reverse complement that leaves IUPAC codes unchanged. AccI (GT\\^{{}}MKAC) is in fact palindromic under IUPAC complementation (M$\\leftrightarrow$K), but the plain reverse complement GTKMAC was searched as a second pattern, which matches GTGAAC and GTTCAC, neither an AccI site. On pBR322 this gave 5 AccI sites where Biopython finds 2. Second, on linear DNA the finder reported Type IIS cuts that fall outside the molecule. After the fix (sugarcode-ai fe2185d), {r['J01749.1']['agree']} and {r['NC_001416.1']['agree']} enzymes agree. The remaining two, "+', '.join(d['enzyme'] for d in r['J01749.1']['disagree'])+", are modification-dependent enzymes that do not cut unmethylated DNA; we leave them open.")
o.append('\\paragraph{(F41) IUPAC complement.} The map $c$: A$\\leftrightarrow$T, C$\\leftrightarrow$G, R$\\leftrightarrow$Y, K$\\leftrightarrow$M, B$\\leftrightarrow$V, D$\\leftrightarrow$H, with S, W, N fixed, is the unique involution on the 15 codes that complements every base in the set a code denotes. A site $s$ is palindromic iff $s=\\overline{c(s)}$ (reversed), which for AccI holds only under $c$, not under the four-letter map.')
o.append('\\subsection{Stockholm alignments}')
o.append(f"bio.stockholm parsed {sto['n_alignments']} Rfam seed alignments ({sto['total_sequences']:,} sequences). {sto['n_all_match']}/{sto['n_alignments']} match Biopython on sequence identifiers and order, aligned sequences and SS\\_cons, and survive a write--parse round trip unchanged.")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{llrrc}\\hline file & AC & seqs & width & all checks\\\\\\hline')
for x in sto['per_alignment']: o.append(f"{esc(x['file'].split('/')[-1])} & {esc(x['ac'])} & {x['n_seqs']} & {x['width']} & {'yes' if x['ids_match'] and x['seqs_match'] and x['ss_cons_match'] and x['roundtrip'] else 'no'}\\\\")
o.append('\\hline\\end{tabular}\\caption{bio.stockholm vs Biopython AlignIO (benchmarks/sweep\\_stockholm\\_biopython.json).}\\end{table}')
o.append('\\paragraph{(F42) Pairwise identity.} $\\mathrm{PID}(x,y)=\\#\\{i: x_i=y_i,\\ x_i,y_i\\notin\\{-,.\\}\\}\\,/\\,\\#\\{i: x_i,y_i\\notin\\{-,.\\}\\}$, case-insensitive; our implementation equals an independent count on every file.')
o.append('\\subsection{GFF3 annotation}')
o.append(f"On the RefSeq E. coli K-12 annotation ({gf['n_records_sugarcode']:,} records), bio.gff and {esc(gf['reference'])} agree on every record ({gf['records_identical']:,}/{gf['n_features_gffutils']:,}) and on the children of {gf['children_identical_multiset']}/{gf['genes_checked_children']} genes, and write--parse is lossless. A first comparison showed two child mismatches; both were CDS features split over two lines with a shared ID, which gffutils renames X\\_1. That was a comparison artifact, not a sugarcode error, and we record it so the numbers are traceable.")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{lr}\\hline feature type & records\\\\\\hline')
for t,n in gf['types']: o.append(f"{esc(t)} & {n}\\\\")
o.append('\\hline\\end{tabular}\\caption{Feature types in GCF\\_000005845.2 (benchmarks/sweep\\_gff\\_gffutils.json).}\\end{table}')
nk=json.load(open(B+'sweep_newick_biophylo.json'))
o.append('\\subsection{Newick trees}')
o.append(f"bio.newick parsed {nk['n_trees']} Open Tree of Life synthetic subtrees with {nk['total_leaves']:,} leaves in total, including quoted labels with spaces and parentheses and empty leaves left by the height limit. Leaf sets equal Biopython Bio.Phylo and DendroPy, internal-node counts and internal labels equal Bio.Phylo, and write--parse is lossless in {nk['n_all_pass']}/{nk['n_trees']} trees. These trees have no branch lengths, so this checks topology and labels only.")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{lrrrc}\\hline root & leaves & unnamed & internal & all checks\\\\\\hline')
for x in nk['per_tree']: o.append(f"{esc(x['root'])} & {x['leaves']} & {x['unnamed_leaves']} & {x['internal']} & {'yes' if x['leaves_eq_biopython'] and x['internal_count_eq_biopython'] and x['internal_labels_eq_biopython'] and x['leaves_eq_dendropy'] and x['roundtrip'] else 'no'}\\\\")
o.append('\\hline\\end{tabular}\\caption{bio.newick vs Bio.Phylo/DendroPy (benchmarks/sweep\\_newick\\_biophylo.json).}\\end{table}')
o.append('\\paragraph{(F43) Tree size identity.} For a rooted tree with $n$ leaves, $m$ internal nodes and out-degrees $d_v$, the edge count is $n+m-1=\\sum_{v\\,\\mathrm{internal}}d_v$; a strictly binary tree has $m=n-1$. The Carnivora subtree has 53 leaves and 48 internal nodes, so it is far from binary, which exercises the parser on polytomies.')
sm=json.load(open(B+'sweep_sam_pysam.json'))
o.append('\\subsection{SAM records and a second bug}')
fe=sm['fields_equal']
o.append(f"bio.sam parsed {sm['n_sugarcode']:,} real reads ({esc(sm['source'])}). Name, flag, reference, position, mapping quality, CIGAR operations, mate fields, sequence, qualities and typed tags equal pysam for all {fe['qname']:,} reads. The derived reference end did not: {sm['before_fix']['alignment_end']:,}/{sm['n_sugarcode']:,} before the fix. The {sm['n_sugarcode']-sm['before_fix']['alignment_end']} failures were unmapped mates (flag 0x4) that bwa places at the mapped mate's position and gives a CIGAR. The SAM specification says those fields are not an alignment, and htslib reports no end; sugarcode computed one. After sugarcode-ai {sm['after_fix_commit']} all {fe['alignment_end']:,} agree.")
o.append('\\paragraph{(F44) Reference span of a CIGAR.} $\\mathrm{end}=\\mathrm{POS}+\\sum_{(n,o)\\in C,\\ o\\in\\{M,D,N,=,X\\}}n-1$ for mapped reads (1-based, inclusive); query length is $\\sum_{o\\in\\{M,I,S,=,X\\}}n$. For flag $\\&\\,4\\ne0$ the end is undefined.')
fq=json.load(open(B+'sweep_fastq_biopython.json'))
o.append('\\subsection{FASTQ reads}')
o.append(f"On the first {fq['n_sugarcode']:,} reads of ENA run SRR622461 (the same NA12878 library), bio.fastq equals Biopython on identifiers ({fq['ids_equal']:,}), sequences ({fq['seqs_equal']:,}) and per-base Phred scores ({fq['phred_equal']:,}), detects offset {fq['detected_offset']}, and round-trips losslessly. GC was {fq['gc_sugarcode']} against {fq['gc_biopython_remove_N']} (Biopython, ambiguous bases removed) and {fq['gc_biopython_ignore_N']} (ambiguous bases kept in the denominator). The difference is a convention: sugarcode divides by A+C+G+T. We document it rather than change it.")
o.append('\\paragraph{(F45) Phred score.} $Q=-10\\log_{10}P_{err}$, encoded as ASCII $Q+33$; the mean read quality reported is the arithmetic mean of $Q$, not $-10\\log_{10}$ of the mean error probability, which would be lower for reads with a few bad bases.')
pg=json.load(open(B+'sweep_pdb_gemmi.json'))
o.append('\\subsection{PDB and mmCIF structures: a third bug}')
o.append(f"We parsed {pg['n_entries']} RCSB entries in both PDB and mmCIF format ({pg['atoms_total_pdb']:,} atom sites, all alternate locations and models) and compared every atom with {esc(pg['reference'])}. The PDB-format parser was identical in {pg['before_fix']['pdb_identical']}/{pg['n_entries']} entries. The mmCIF parser failed on all {pg['n_entries']} real files (error: {esc(pg['before_fix']['cif_error'])}). Two causes: POSIX shell-style splitting broke atom names containing a prime (O5$'$, C1$'$), and loops were closed early when a row contained an unquoted item name as a value, which RCSB files do in the revision-history tables. A CIF 1.1 tokenizer (a quote closes only when followed by whitespace) and closing loops only at row boundaries fixed both (sugarcode-ai {pg['after_fix_commit']}); mmCIF is now identical to gemmi in {pg['cif_identical']}/{pg['n_entries']} entries. Unit tests with toy CIF strings had passed throughout. Only real files exposed the bug.")
o.append('\\paragraph{(F46) Loop row invariant.} A loop with $c$ columns and $t$ value tokens is well formed iff $t\\equiv0\\pmod c$; closing the loop at the first reserved-looking token is only safe when the running count $t\\bmod c=0$, which is the rule we now apply.')
pu=json.load(open(B+'sweep_pileup_pysam.json'))
o.append('\\subsection{Pileup}')
o.append(f"Using the same reads, bio.pileup and {esc(pu['reference'])} agree on base counts at {pu['base_counts_equal']:,}/{pu['n_positions_union']:,} positions and on deletion counts at {pu['deletion_counts_equal']:,}/{pu['n_positions_union']:,}. sugarcode also writes deletions as `*' in the base counts, following samtools mpileup; the comparison maps these to the deletion count.")
o.append('\\paragraph{(F49) Column depth.} $D(p)=\\sum_{r}\\mathbb 1[p\\in[\\mathrm{POS}_r,\\mathrm{end}_r]\\ \\wedge\\ \\mathrm{op}_r(p)\\in\\{M,=,X,D\\}]$, split into base-covering reads ($M,=,X$) and deletions ($D$); reference skips ($N$) and clipped bases do not count.')
mo=json.load(open(B+'sweep_motif_biopython.json'))
o.append('\\subsection{Transcription-factor motifs}')
o.append(f"We read {mo['n_motifs']} JASPAR 2024 profiles and scanned BRCA1 (10 kb) and phage lambda (48.5 kb) on both strands, comparing with {esc(mo['reference'])}. Log-odds matrices agree to $2\\times10^{{-15}}$, per-window scores to $4\\times10^{{-6}}$ (Biopython stores scores in single precision), and the hit sets at 80\\% of the score range are identical for every motif and sequence.")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{lrrr}\\hline motif & length & hits BRCA1 & hits lambda\\\\\\hline')
for r in mo['per_motif']: o.append(f"{esc(r['motif'].replace(chr(9),' '))} & {r['length']} & {r['brca1_10kb.fa']['hits_sugarcode']} & {r['NC_001416.1.fa']['hits_sugarcode']}\\\\")
o.append('\\hline\\end{tabular}\\caption{Motif hits at 80\\% of range, identical to Biopython (benchmarks/sweep\\_motif\\_biopython.json).}\\end{table}')
o.append('\\paragraph{(F50) Log-odds score and relative threshold.} $S(w)=\\sum_{i=1}^{L}\\log_2\\frac{(c_{i,w_i}+\\alpha)/(N_i+4\\alpha)}{q_{w_i}}$ with pseudocount $\\alpha=0.5$ and background $q=1/4$; a window is a hit when $S(w)\\ge S_{\\min}+f\\,(S_{\\max}-S_{\\min})$, $f=0.8$, where $S_{\\max}=\\sum_i\\max_b$ and $S_{\\min}=\\sum_i\\min_b$ of the log-odds matrix.')
bd=json.load(open(B+'sweep_bed_bioframe.json'))
rm=bd['sets']['rmsk_chr20_0_5Mb']; cg=bd['sets']['cpgIslandExt_chr20']
o.append('\\subsection{BED intervals: a fourth bug}')
o.append(f"We fetched two hg38 tracks from the UCSC REST API: CpG islands on chr20 ({cg['n']} intervals) and RepeatMasker on chr20:0--5\\,Mb ({rm['n']:,} intervals), wrote them as BED and compared bio.bed with {esc(bd['reference'])}. Parsing and 600 random overlap queries agreed exactly ({cg['overlap_sets_equal']}/300 and {rm['overlap_sets_equal']}/300). merge\\_intervals did not: its docstring promised bedtools-style merging, yet it refused to join book-ended intervals. RepeatMasker has {rm['bookended_pairs_in_input']:,} book-ended pairs, so sugarcode returned {bd['before_fix']['rmsk_chr20_0_5Mb_merged_sugarcode']:,} merged intervals where bedtools/bioframe return {rm['merged_bioframe_min_dist0']:,}. CpG islands have no book-ended pairs and hid the bug (847 = 847). We added a bedtools-compatible min\\_dist argument (default 0; $-1$ for overlap-only) and a matching CLI flag; after the fix both tracks match bioframe exactly ({rm['merged_sugarcode']:,} = {rm['merged_bioframe_min_dist0']:,}).")
o.append('\\paragraph{(F51) Merge rule.} For intervals sorted by start with running end $e^*$, interval $[s,e)$ joins the current block iff $s\\le e^*+d$; $d=0$ joins book-ended intervals ($s=e^*$) and $d=-1$ requires at least one shared base ($s<e^*$).')
gb=json.load(open(B+'sweep_genbank_biopython.json')); gt=gb['totals']; gbt=gb['before_fix']['totals']
o.append('\\subsection{GenBank flat files: a fifth bug}')
o.append(f"We fetched {gt['records']} GenBank records one by one from NCBI nuccore (phage, viral, mitochondrial, bacterial, RefSeqGene and 13 human RefSeq mRNAs) and compared bio.genbank with {esc(gb['reference'])} on {gt['features_bio']:,} features. Sequences and feature counts already agreed, but only {gbt['spans_equal']:,}/{gt['features_bio']:,} feature locations and {gbt['translation_q_equal']}/{gt['translation_q_total']} CDS /translation qualifiers matched. The parser appended every continuation line of a multi-line qualifier to the feature location instead of to the qualifier: /translation kept its first line only, and when a continuation began with digits the location itself was corrupted (E.~coli thrA CDS: 337..2799 became 337..27991). Partial locations (<1..>200) and single bases produced no spans at all. We rewrote qualifier continuation (INSDC joining: no spaces for /translation, one space otherwise, doubled quotes unescaped), added a location parser for join/order, complement, partial ends, between-base sites and remote parts, and kept all IUPAC letters in ORIGIN so coordinates cannot shift. After the fix: spans {gt['spans_equal']:,}/{gt['features_bio']:,}, strands {gt['strand_equal']:,}/{gt['features_bio']:,}, /translation {gt['translation_q_equal']}/{gt['translation_q_total']}, CDS extraction {gt['cds_extract_equal']}/{gt['cds_total']}.")
o.append("The fix exposed a downstream case: KCNQ1's record NG\\_016178.2 carries only a partial CDS, complement(<42918..>43038). The old parser read no spans and bio.splice reported 'no CDS spans'; with spans read, the junction map came back 'ok' but empty. We made it fail loud with status 'partial CDS in record'. The splice-region discovery pipeline reads hg38 directly and does not use this parser, so its results are unchanged.")
o.append('\\paragraph{(F52) Qualifier continuation.} For a qualifier whose value spans lines $\\ell_1,\\dots,\\ell_m$, $v=\\ell_1\\oplus_\\sigma\\ell_2\\oplus_\\sigma\\cdots\\oplus_\\sigma\\ell_m$ with separator $\\sigma=\\varnothing$ for /translation and $\\sigma=$ one space otherwise; a line starting with / opens a new qualifier only when the running count of quote characters in $v$ is even.')
sq=json.load(open(B+'sweep_sequence_biopython.json')); tr=sq['translate']; mw=sq['molecular_weight']; orf=sq['orfs_min100']
o.append('\\subsection{Core sequence operations}')
o.append(f"On the same {sq['n_records']} GenBank records, bio.sequence.translate reproduced the /translation qualifier for {tr['eq_qualifier']}/{tr['cds']} standard-code CDSs ({tr['skipped_other_table_or_frame']} CDSs with other genetic codes, codon\\_start$\\ne$1, transl\\_except or ribosomal slippage were set aside) and matched Bio.Seq.translate on all {tr['eq_bio']}. Reverse complements agreed on {sq['revcomp_equal']}/{sq['n_records']} whole records, IUPAC motif search on {sq['find_motif']['equal']}/{sq['find_motif']['queries']} (motif, record) pairs, Wallace $T_m$ on {sq['tm_wallace_short']['equal']}/{sq['tm_wallace_short']['n']} lambda oligos (8--13 nt), and ORF calls ($\\ge$100 aa, both strands) on {orf['equal']}/{orf['records']} records ({orf['n_orfs_ours']} = {orf['n_orfs_bio']} ORFs) against an independent Biopython frame scan. GC fraction agreed to $10^{{-12}}$ on {sq['gc_equal_1e12']}/{sq['n_records']}; the exception is the human mitochondrial genome, whose single N sugarcode leaves out of the denominator. Protein masses on {mw['n']} UniProt proteins differ from ProteinAnalysis by at most {mw['max_rel']:.1e} (relative), from two-decimal residue masses.")
o.append("Reading the code for this comparison turned up a latent bug the data could not: clean\\_dna silently dropped IUPAC ambiguity letters, so ATGRCTTAA translated as ML (frame shifted) instead of MX. No CDS in this set carries an ambiguity code, so the real-data numbers are identical before and after; ambiguity letters now become N (sugarcode 143d1c4), with a regression test. We report it as a code-review finding, not a data finding.")
o.append('\\paragraph{(F53) Frame preservation.} Cleaning must be a letter-wise map $c:\\Sigma\\to\\{A,C,G,T,N\\}\\cup\\{\\epsilon\\}$ with $c(x)=\\epsilon$ only for non-letters; then codon $k$ of the cleaned sequence is $c(s_{3k})c(s_{3k+1})c(s_{3k+2})$ and every downstream codon keeps its frame.')
km=json.load(open(B+'sweep_kmer_sourmash.json')); ks=km['summary']
rt=[q for q in km['pairs'] if {q['a'],q['b']}=={'MN996532.2','NC_045512.2'}][0]
o.append('\\subsection{k-mer sets and sketches: exact agreement, a biased estimator}')
o.append(f"We fetched six coronavirus genomes (SARS-CoV-2, bat RaTG13, pangolin GX-P4L, SARS-CoV Tor2, bat ZC45, MERS) and compared bio.kmer with {esc(km['reference'])} at $k={km['k']}$. With sourmash keeping every hash (scaled=1), distinct canonical k-mer counts agreed for {ks['distinct_counts_equal']}/6 genomes, and Jaccard and containment agreed exactly on all {ks['n_pairs']} pairs (maximum difference {ks['max_abs_diff_exact_jaccard']}).")
o.append(f"The sketch estimator is a negative result. bio.kmer's minimizer sketch (window $w=100$, about 600 k-mers per genome) under-estimated Jaccard: for SARS-CoV-2 vs RaTG13 the exact value is {rt['jaccard_exact_sugarcode']:.3f}, the minimizer estimate {rt['minimizer_w100_estimate']:.3f} and sourmash FracMinHash (scaled=100, about 300 hashes) {rt['sourmash_scaled100_estimate']:.3f}. Across the 15 pairs the mean absolute error was {ks['sketch_mae_sugarcode_minimizer_w100']:.4f} for minimizers and {ks['sketch_mae_sourmash_scaled100']:.4f} for FracMinHash, with half the sketch size. Jaccard over minimizer sets is known to be biased because sequence changes shift which k-mer wins each window; FracMinHash keeps a k-mer if and only if its hash falls below a fixed threshold, so the kept subset is a uniform sample of the union. The module's docstring already labels the values as estimates; we record the bias and do not recommend minimizer Jaccard for distance estimation.")
o.append('\\paragraph{(F54) FracMinHash estimator.} With hash $h$ and threshold $H/s$, $\\mathrm{FMH}_s(A)=\\{a\\in A:h(a)<H/s\\}$ and $\\hat J=|\\mathrm{FMH}_s(A)\\cap\\mathrm{FMH}_s(B)|/|\\mathrm{FMH}_s(A\\cup B)|$, which is (nearly) unbiased because inclusion depends on the k-mer alone; the Mash distance is $D=-\\tfrac1k\\ln\\tfrac{2J}{1+J}$.')
gs=json.load(open(B+'sweep_gstats_scipy.json')); hw=gs['hwe']; asc=gs['association_EUR_vs_EAS']
o.append('\\subsection{Population-genetics statistics on 1000 Genomes}')
o.append(f"We pulled 1000 Genomes phase 3 genotype counts for {len({r['rs'] for r in gs['rows']})} well-studied SNPs (APOE, LCT, SLC24A5, HERC2, ALDH2, ABCC11, ADH1B, EDAR, F5, HFE, MTHFR, COMT and others) from the Ensembl GRCh37 REST service, one record per rsID, giving {hw['n_tests']} (SNP, super-population) genotype tables. bio.gstats.hwe\\_exact matched an independent full enumeration of the exact HWE distribution on {hw['n_rel_err_lt_1e-6']}/{hw['n_tests']} tables (maximum relative error {hw['max_rel_err']:.1e}); {hw['n_p_lt_0.05']} tables have $p<0.05$, as expected for a set that includes SNPs with strong population structure inside super-populations. Treating EUR as `cases' and EAS as `controls' for {asc['n_snps']} SNPs, allelic chi-square (with and without Yates), genotypic chi-square and Woolf odds ratios matched scipy and statsmodels to $\\le${max(asc['pearson_p_max_rel'],asc['yates_p_max_rel'],asc['genotypic_p_max_rel'],asc['or_max_rel']):.0e} relative error, and Benjamini-Hochberg and Bonferroni adjustments matched statsmodels exactly (maximum difference {gs['multiple_testing']['bh_max_abs']:.0e}). No bug was found in this module.")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{llrrrr}\\hline SNP & alleles & EUR (AA/AB/BB) & EAS (AA/AB/BB) & allelic $\\chi^2$ & OR\\\\\\hline')
by={(r['rs'],r['pop']):r for r in gs['rows']}
for a in sorted(gs['assoc'],key=lambda a:-a['pearson']['stat_sc']):
    e=by[(a['rs'],'EUR')]; c=by[(a['rs'],'EAS')]
    o.append(f"{a['rs']} & {e['A']}/{e['B']} & {'/'.join(map(str,e['counts']))} & {'/'.join(map(str,c['counts']))} & {a['pearson']['stat_sc']:.1f} & {a['or']['sc'][0]:.3g}\\\\")
o.append('\\hline\\end{tabular}\\caption{EUR vs EAS allele-frequency contrasts from 1000 Genomes phase 3, computed by bio.gstats and matching scipy/statsmodels (benchmarks/sweep\\_gstats\\_scipy.json).}\\end{table}')
o.append('\\paragraph{(F55) Exact HWE distribution.} For $n$ individuals with $n_A$ copies of allele A and $n_B=2n-n_A$, the probability of $h$ heterozygotes is $P(h)=\\dfrac{n!}{n_{AA}!\\,h!\\,n_{BB}!}\\,\\dfrac{2^{h}\\,n_A!\\,n_B!}{(2n)!}$ with $n_{AA}=(n_A-h)/2$, $n_{BB}=(n_B-h)/2$; the two-sided p-value is $\\sum_{h:P(h)\\le P(h_{obs})}P(h)$.')
uh=json.load(open(B+'sweep_uniprot_hgnc.json'))
o.append('\\subsection{UniProt lookup: a wrong protein and a cache that never hit}')
o.append(f"bio.uniprot.search maps a gene symbol to its UniProt entry, and several modules (binding sites, mutation docking) build on it. We checked it against HGNC's curated symbol-to-UniProt mapping for {uh['n']} human genes, fetching each HGNC record separately. Before the fix {uh['before_fix']['match']}/{uh['n']} matched. The miss was CDKN2A: the query gene:CDKN2A also matches CDKN2A-AS1, and taking the top hit returned Q9UH64 (the antisense-locus protein) instead of P42771 (p16-INK4a). We switched to gene\\_exact and prefer the entry whose primary gene name equals the symbol; after the fix {uh['match']}/{uh['n']} match and all {uh['length_ok']} returned sequences have the length of the entry fetched by accession.")
o.append("Reading the connector turned up a second bug. The on-disk cache named each file by abs(hash(url)); Python salts string hashes per process, so a new process never found its own cache and offline=True always failed. The same pattern was in the ChEMBL, gnomAD and structure connectors. All four now use SHA-256, and a new process running offline reads TP53 and CDKN2A from cache (P04637, P42771).")
o.append('\\paragraph{(F56) Stable cache key.} A cache key must be a pure function of the request, $k(u)=\\mathrm{SHA256}(u)$; a per-process salted hash $k_s(u)$ gives $\\Pr[k_{s_1}(u)=k_{s_2}(u)]\\approx2^{-64}$ for independent salts, so the hit rate across processes is effectively zero.')
ez=json.load(open(B+'sweep_entrez_hgnc.json'))
o.append('\\subsection{NCBI Gene lookup: Huntington resolved to the serotonin transporter}')
o.append(f"bio.entrez.gene\\_id resolves a symbol to an NCBI Gene ID and feeds the gene-analysis module. Against HGNC's curated Gene IDs for the same {ez['n']} symbols it scored {ez['before_fix']['match']}/{ez['n']}. HTT returned 6532, which is SLC6A4 (the serotonin transporter, alias HTT), not huntingtin (3064); TTN returned 7276, which is TTR (transthyretin, alias TTN), not titin (7273). The query field [sym] also matches aliases and the search took the top hit. The function now fetches up to ten hits and returns the one whose official symbol equals the query; after the fix {ez['match']}/{ez['n']} match (sugarcode 93d5b12). For a user asking about Huntington disease or titin cardiomyopathy the old answer would have been about the wrong gene.")
o.append('\\paragraph{(F57) Symbol resolution rule.} Given candidate IDs $u_1,\\dots,u_r$ from an alias-aware search, return $u^*=u_{\\min\\{i:\\,\\mathrm{sym}(u_i)=q\\}}$ if that set is non-empty, else $u_1$; an alias match is used only when no official-symbol match exists.')
rx=json.load(open(B+'sweep_reactome_download.json'))
o.append('\\subsection{Reactome pathway mapping}')
o.append(f"bio.reactome.pathways\\_for\\_uniprot asks Reactome's live ContentService which lowest-level pathways contain a protein. As an independent check we used Reactome's own bulk file UniProt2Reactome.txt for the {rx['n_accessions']} HGNC-curated UniProt accessions of our 60 genes. A first comparison against canonical-accession rows matched only 59/61: KRAS (P01116) has 9 canonical rows but the service returned 71 pathways, and LMNA (P02545) 2 vs 8. The service pools the isoform rows (P01116-1, P01116-2); pooling them in the file gives {rx['equal_sets']}/{rx['n_accessions']} identical sets ({rx['pairs_live']} = {rx['pairs_file']} protein-pathway pairs). No bug, but a caveat for users: KRAS4A and KRAS4B pathways come back together.")
cb=json.load(open(B+'sweep_chembl_order.json'))
o.append('\\subsection{ChEMBL activities: ``best first\' from an arbitrary page}')
o.append(f"bio.chembl.activities\\_for\\_target promises measured IC50/Ki/Kd values `best first'. It fetched the first 50 rows in ChEMBL's default order and sorted those, so `best' meant best of an arbitrary page. On 12 cancer and CNS targets (between {min(r['total_activities'] for r in cb['rows']):,} and {max(r['total_activities'] for r in cb['rows']):,} activities each) the old top-10 shared at most one molecule with the true top-10, and the reported best was far from the real one; for ABL1 it was {cb['before_fix']['ours_best_nM']['ABL1']:,.0f} nM when ChEMBL holds exact measurements at 0.015 nM. The function now asks ChEMBL to sort all activities that carry a pChEMBL value by pChEMBL, descending (sugarcode c6db085). The best value now equals the best pChEMBL-valid measurement on {cb['n_ours_best_equals_best_valid_pchembl']}/{cb['n_targets']} targets; this check is partly circular because the reference uses the same ordering, so the evidence for the bug is the before-fix column. Restricting to pChEMBL also drops data-entry artefacts that sort first by raw value: 0.0 nM (JAK2, IDH1), $5\\times10^{{-9}}$ nM (EGFR) and $-0.63$ nM (DRD2).")
o.append('\\begin{table}[h]\\centering\\small\\begin{tabular}{lrrrr}\\hline target & activities & best before (nM) & best after (nM) & pChEMBL\\\\\\hline')
for r in cb['rows']: o.append(f"{r['gene']} & {r['total_activities']:,} & {cb['before_fix']['ours_best_nM'][r['gene']]:g} & {r['ours_min_nM']:g} & {r['ours_best_pchembl']:.2f}\\\\")
o.append('\\hline\\end{tabular}\\caption{Best reported activity per target before and after the fix (benchmarks/sweep\\_chembl\\_order.json).}\\end{table}')
o.append('\\paragraph{(F58) pChEMBL.} $\\mathrm{pChEMBL}=-\\log_{10}(A\\cdot10^{-9})$ for an activity $A$ in nM with an exact relation; ranking by pChEMBL descending equals ranking by $A$ ascending on valid records, and $A\\le0$ has no pChEMBL.')
gn=json.load(open(B+'sweep_gnomad_constraint.json'))
o.append('\\subsection{gnomAD constraint: a version-2 cutoff on version-4 data}')
o.append(f"bio.gnomad.gene\\_constraint reads pLI and LOEUF from gnomAD r4 and flags a gene as strongly loss-of-function constrained when LOEUF $<0.35$. That cutoff comes from gnomAD v2. gnomAD's own help page says v4 o/e and LOEUF values run higher than v2, that v2 thresholds do not transfer, and suggests LOEUF $<0.45$ (the most constrained 15\\% of 17,063 MANE Select transcripts) for Mendelian interpretation. Under the old cutoff TP53 (LOEUF 0.418, pLI $>0.999$) was called `not strongly constrained'. On our {gn['n_scored']} genes the old rule flagged {gn['constrained_old_035']} and the v4 rule flags {gn['constrained_new_045']}; the newly flagged genes are {', '.join(gn['flipped_to_constrained'])}. Agreement with the independent pLI $>0.9$ call rose from {gn['agree_pli_old']}/{gn['n_scored']} to {gn['agree_pli_new']}/{gn['n_scored']} (sugarcode 0a265e7). The sweep also hit gnomAD's API rate limit (HTTP 400, `try again in a few minutes'); the connector used to retry three times within about 1.5\\,s, which only burns quota, and now fails fast with a distinct rate-limit error so callers can wait or fall back to the cache.")
o.append('\\paragraph{(F59) LOEUF.} With observed pLoF count $O$ and neutral expectation $E$, $\\mathrm{LOEUF}=q_{0.95}(\\lambda\\mid O)/E$ where the posterior of the true count is $\\lambda\\mid O\\sim\\mathrm{Gamma}(O+1,1)$ under a flat prior and Poisson likelihood; a gene is flagged when $\\mathrm{LOEUF}<\\tau_{v}$ with version-specific $\\tau_{v4}=0.45$.')
spc=json.load(open(B+'sweep_splice_clinvar.json'))
o.append('\\subsection{Splice-junction maps against ClinVar canonical-site variants}')
o.append(f"bio.splice.junction\\_map builds donor and acceptor windows, keyed by cDNA position, from each gene's RefSeqGene record, taking the CDS with the most exons as canonical. ClinVar names canonical splice-site variants on the MANE Select transcript (c.N+1, c.N+2, c.N-1, c.N-2), which gives an independent test of both the numbering and the sequence: the named position must be a junction in the map, and the base at the named intronic offset must equal ClinVar's reference allele. We queried {len(spc['per_gene'])} genes; CDH1 is not in the module's vendored RefSeqGene list and gets an explicit `no RefSeqGene junction map' status rather than a guess (a coverage limit, noted for follow-up). Across the other 11 (TP53, BRCA1, BRCA2, MLH1, MSH2, APC, PTEN, ATM, PALB2, CFTR, NF1) ClinVar returned {spc['total']} such SNVs. The map had the junction for {spc['junction_found']} and the right reference base for {spc['ref_base_ok']}; the two misses are named on other transcripts (KCNK12, a neighbouring gene returned by the MSH2 search, and a non-MANE APC isoform). The `most exons' rule picked the MANE transcript for every gene here, NF1 included. A first run of our own checker scored 96 because it assumed 15 intronic bases in the acceptor window; the windows hold 14 intronic bases plus the first exonic base, consistently across all three map builders. No module bug.")
o.append('\\paragraph{(F60) Window offsets.} For a donor at exon end $b$ the window is $x_{b-2}\\dots x_{b+6}$, so intronic position $+k$ is index $2+k$; for an acceptor at exon start $c$ the window is $x_{c-14}\\dots x_{c}$, so intronic position $-k$ is index $14-k$ (0-based); on the minus strand both windows are reverse-complemented before indexing.')
cf=json.load(open(B+'sweep_cfd_doench.json'))
o.append('\\subsection{CFD off-target scores}')
o.append(f"modules.cfd\\_offtarget scores guide/off-target pairs with the Cutting Frequency Determination model. We re-implemented the scoring loop of the authors' published calculator on their released matrices (mismatch\\_score.pkl, pam\\_scores.pkl) and scored the {cf['n_pairs']} BRCA1 guide/off-target pairs against all {cf['pams']} PAM dinucleotides: {cf['exact_1e-12']:,}/{cf['n_scores']:,} scores agree, maximum difference {cf['max_abs_diff']:.1e}. No bug.")
o.append('\\paragraph{(F61) CFD score.} $\\mathrm{CFD}(g,o,p)=\\pi(p_2p_3)\\prod_{i:\\,g_i\\ne o_i} m\\big(\\mathrm{r}g_i{:}\\mathrm{d}\\overline{o_i},\\,i\\big)$, where $\\overline{o_i}$ is the complement of the off-target base, $m$ the position-specific mismatch activity and $\\pi$ the PAM activity.')
st=json.load(open(B+'sweep_str_pytrf.json'))
o.append('\\subsection{Short tandem repeats: a flank homopolymer hid compound repeats}')
o.append(f"modules.str\\_scope.find\\_strs finds tandem repeats with 1--6 bp units. We ran it and pytrf 1.5.0 (the finder behind Krait and TRF-style pipelines) with pytrf's default minimum repeat counts (12/7/5/4/4/4 for mono- to hexanucleotides) on all {len(st['genomes'])} GenBank records in our dataset set, from phiX174 to a {max(g['length'] for g in st['genomes']):,}-bp RefSeqGene region. Before the fix sugarcode found {st['pre_fix']['matched']} of pytrf's {st['pre_fix']['pytrf']} repeats and nothing pytrf missed. The three losses had one cause: the scan moved left to right and, after taking a short homopolymer, jumped to the end of that run, past the start of an overlapping longer repeat. In HSV-1 (NC\\_001806.2) a seven-base G run swallowed the start of (GGGGTT)$_4$; in NG\\_005905.2 T and A runs did the same to (TTTTG)$_4$ and (AAAT)$_4$. The finder now takes every maximal periodic run at every unit length and resolves overlaps longest first, trying the other phases of a run before dropping it (sugarcode 727344a). After the fix it finds {st['totals']['matched']}/{st['totals']['pytrf']}, with {st['totals']['only_ours']} extra calls; {st['totals']['exact_span']} have identical coordinates and the other {st['totals']['matched']-st['totals']['exact_span']} are the same span reported in the disease-motif phase (CGG rather than GCG in PTEN's 5' UTR), which the module does on purpose.")
ab=st['allele_bands']
o.append(f"The same module labels repeat genotypes. The old rule used only the distance from a normal upper bound (normal if $\\le2$ above it, intermediate up to 10 above, else `pathogenic-range candidate'). Compared with the GeneReviews allele tables it mislabels HTT CAG counts {', '.join(map(str,ab['HTT_legacy_misclassified']))} (27 and 28 are intermediate, 36 is reduced-penetrance pathogenic) and {ab['FMR1_legacy_misclassified_count_5_300']} FMR1 CGG counts between 5 and 300, from {ab['FMR1_legacy_misclassified_ranges'][0]} to {ab['FMR1_legacy_misclassified_ranges'][1]}: every premutation allele (55--200) was called a pathogenic expansion, which in counselling terms confuses a carrier with an affected full-mutation allele. expansion\\_call now takes an optional locus and uses the published bands for HTT and FMR1 ({ab['banded_errors']} disagreements on HTT 5--120); without a locus the old behaviour is unchanged.")
o.append('\\paragraph{(F62) Maximal periodic runs.} For unit length $u$, position $j$ is periodic if $x_j=x_{j+u}$; a maximal run of periodic positions $[a,b)$ defines the span $[a,b+u)$ holding $\\lfloor (b+u-a-k)/u\\rfloor$ whole units from phase $k\\in\\{0,\\dots,u-1\\}$. Candidates over all $u$ are kept greedily by length (ties: smaller $u$, then leftmost) subject to disjoint whole-unit intervals, which is the rule pytrf-style finders apply implicitly by reporting the longest repeat at each locus.')
ac=json.load(open(B+'sweep_acmg_erepo.json'))
o.append('\\subsection{Bayesian ACMG scoring against ClinGen expert panels}')
o.append(f"modules.acmg\\_bayesian scores ACMG/AMP criteria with the Tavtigian et al.\\ (2018) Bayesian model in its point form (supporting 1, moderate 2, strong 4, very strong 8; pathogenic $\\ge10$, likely pathogenic 6--9, likely benign $-1$ to $-6$, benign $\\le-7$). The ClinGen Evidence Repository publishes, for every variant a Variant Curation Expert Panel (VCEP) has classified, the criteria it applied and its final call. We used {ac['n']:,} current classifications from {ac['n_expert_panels']} panels across {ac['n_genes']} genes (the server closed the bulk download after about 18 MB, so only complete rows were used). ClinGen writes modified strengths as suffixes: PM2\\_Supporting, PVS1\\_Strong, PM3\\_Very Strong, BS1\\_Stand Alone. The module accepted a strength only as a separate field, so in {ac['pre_fix']['rows_with_rejected_codes']:,} rows at least one code was rejected, and it reproduced {ac['pre_fix']['bayesian_agree']:,}/{ac['n']:,} panel calls. The rejections were listed in the output rather than hidden, but anyone pasting ClinGen notation got a wrong class. The parser now reads the suffix, and a stand-alone benign strength acts like BA1 (sugarcode {ac['post_fix_sugarcode_commit']}). The module now reproduces {ac['bayesian_agree']:,}/{ac['n']:,} calls ({100*ac['bayesian_agree']/ac['n']:.1f}\\%), with no rejected codes.")
o.append(f"As a baseline we coded the original ACMG/AMP 2015 combining rules (Richards et al., Table 5), counting each criterion at its applied strength and calling conflicting evidence uncertain. They reproduce {ac['acmg2015_rules_agree']:,}/{ac['n']:,} ({100*ac['acmg2015_rules_agree']/ac['n']:.1f}\\%); the point model is closer to what the panels actually do. The largest remaining disagreement is {ac['bayesian_confusion'].get('Uncertain significance -> Likely benign',0)} variants the panels call uncertain and the model calls likely benign; {ac['single_supporting_benign_vus_to_lb']} of them net to exactly $-1$ point, typically a lone BP4. The 2015 rules need two benign supporting criteria for likely benign, and the panels follow that; the 2018 posterior bands do not. We report this as a known difference and did not change the bands. BA1 with pathogenic criteria also met is rare and panels treat it differently ({', '.join(f'{v} {k.lower()}' for k,v in ac['ba1_with_pathogenic_evidence'].items())}), so the module keeps BA1 as an override but flags the conflict.")
o.append('\\paragraph{(F63) Point form of the Bayesian model.} With prior $\\pi=0.1$ and $O_{PVSt}=350$, a criterion of strength $k$ points has odds $350^{k/8}$; summed points $S$ give posterior $P(S)=\\dfrac{\\tfrac{\\pi}{1-\\pi}350^{S/8}}{1+\\tfrac{\\pi}{1-\\pi}350^{S/8}}$, so $P(10)=0.994$, $P(6)=0.900$, $P(-1)=0.051$ and $P(-7)=0.0007$.')
oc=json.load(open(B+'sweep_openclinvar.json')); cq=oc['consequence']; rs=oc['review_status_stars']
o.append('\\subsection{ClinVar interpretation: exon-spanning ranges and review stars}')
o.append(f"modules.openclinvar infers a variant's molecular consequence from its HGVS name when the name alone decides it, and abstains otherwise. We pulled {oc['n_records']} ClinVar records (60 per gene for BRCA1, BRCA2, TP53, MLH1, MSH2, CFTR, APC, PTEN, LDLR, MYH7, SCN5A and RYR1) and scored the module's call as correct when ClinVar lists that consequence for the record. Of {cq['n_with_clinvar_consequence']} records with a ClinVar consequence the module got {cq['pre_fix']['correct']} right, abstained on {cq['pre_fix']['abstain']} and was wrong on {cq['pre_fix']['wrong']}. All four were ranges judged by their first coordinate only: c.453+625\\_545+920delinsT in MLH1 starts in an intron but removes the exon between two introns, c.5468-64\\_5480dup in BRCA1 runs from the intron into the exon, and c.-19\\_*21del in TP53 deletes the whole coding sequence; the module called them intronic or UTR, the lowest-weight classes in its evidence model. Ranges are now read at both ends: ends in different exon/intron segments mean a boundary is crossed (splice disruption) and a range from the 5' UTR into the CDS removes the start codon (sugarcode {oc['post_fix_sugarcode_commit']}). After the fix: {cq['correct']} right, {cq['abstain']} abstentions, {cq['wrong']} wrong; the remaining one (MSH2 c.2459-2\\_2472del) is annotated by ClinVar on an older transcript, and c.2459-2 is an acceptor-site base, so we kept the call.")
o.append(f"clinvar\\_stars maps a review status to ClinVar's 0--4 gold stars, which weight ClinVar evidence in the module's trace. Against the {rs['n_statuses']} statuses in ClinVar's review-status table it was wrong once: `criteria provided, multiple submitters' (the status used for somatic clinical-impact and oncogenicity classifications) got one star instead of two, because the rule required the germline suffix `no conflicts'. Now {rs['correct_after']}/{rs['n_statuses']}.")
o.append('\\paragraph{(F64) Segment rule for c. ranges.} Write each end as $(a,s,k)$: anchor $a$ (with region 5\\textquotesingle{} UTR, CDS or 3\\textquotesingle{} UTR), intron side $s\\in\\{+,-,\\varnothing\\}$ and offset $k$. Two ends lie in the same segment iff both are exonic, or both are intronic with $(a_1,s_1)=(a_2,s_2)$ or $s_1={+},\\,s_2={-},\\,a_2=a_1+1$. A range whose ends lie in different segments crosses at least one splice site.')
co=json.load(open(B+'sweep_crispr_ontarget_fcres.json')); sp=co['spearman']; pg=co['per_gene_median_spearman']
o.append('\\subsection{CRISPR on-target scores against measured guide activity}')
o.append(f"modules.crispr\\_opt has four on-target scorers: Rule Set 2 (the Azimuth gradient-boosted model, with or without the peptide-position features), Rule Set 1 (Doench 2014 logistic weights), and a hand-built heuristic used only when a guide sits too close to the sequence edge for a 30-mer context. We scored all {co['n_guides']:,} guides in the Doench 2016 FC+RES set ({co['n_genes']} genes; file from the Azimuth repository) and compared with the measured, within-gene rank-normalised activity. Spearman correlations: Rule Set 2 with position {sp['rule_set_2_with_position']}, sequence-only {sp['rule_set_2_sequence_only']}, Rule Set 1 {sp['rule_set_1_doench2014']}, heuristic {sp['heuristic_edge_fallback']}; the repository's own prediction column gives {sp['azimuth_repo_predictions_column']}. Median per-gene values are {pg['rule_set_2_with_position']}, {pg['rule_set_2_sequence_only']}, {pg['rule_set_1_doench2014']} and {pg['heuristic_edge_fallback']}. Both published models were trained on these guides, so their numbers are in-sample and flattering; the heuristic was not fitted and is close to useless ($\\rho\\approx0.11$). Two consequences for users. design\\_guides ranks with Rule Set 1 even though Rule Set 2 ships in the same module; we have not switched it, because the case for switching needs a held-out screen and we have not run one. And the edge fallback should be read as `no reliable score', which the module already labels in its on\\_target\\_model field (heuristic\\_edge\\_fallback). No code bug was found.")
o.append('\\paragraph{(F65) Spearman correlation.} For scores $s$ and measurements $y$ with ranks $R(s_i)$, $R(y_i)$, $\\rho=\\mathrm{corr}\\big(R(s),R(y)\\big)$, which for untied data equals $1-\\dfrac{6\\sum_i d_i^2}{n(n^2-1)}$ with $d_i=R(s_i)-R(y_i)$; the per-gene median guards against between-gene differences in dynamic range.')
pw=json.load(open(B+'sweep_power_statsmodels.json'))
o.append('\\subsection{Replicate planning: a two-entry z table}')
o.append(f"modules.gene\\_analysis.power\\_estimate tells a user how many replicates per group an experiment needs. It added 0.84 to 1.96 when the target power was at most 0.8 and 1.28 otherwise, which is right only at 0.8 and 0.9. Against statsmodels' NormalIndPower solver on {pw['n_cases']} combinations of power (0.5--0.99), effect and variance, the old rule matched {pw['old_equal']} times and over-asked by up to {pw['old_max_ratio']:.2f}$\\times$ (power 0.5 needs 8 replicates for a one-SD effect, it said 16); at 0.95 and 0.99 it under-asked. The function now uses exact normal quantiles and takes alpha as a parameter (sugarcode {pw['sugarcode_commit']}); it matches statsmodels in {pw['new_equal']}/{pw['n_cases']} cases. This is a formula check, not a real-data sweep, and the rest of gene\\_analysis is not yet validated.")
o.append('\\paragraph{(F66) Two-sample size.} For a two-sided test at level $\\alpha$ with power $1-\\beta$, difference $\\delta$ and per-observation variance $\\sigma^2$, $n=\\big\\lceil 2\\sigma^2(z_{1-\\alpha/2}+z_{1-\\beta})^2/\\delta^2\\big\\rceil$ per group.')
qd=json.load(open(B+'sweep_qsar_descriptors.json')); qa=qd['agreement']; qp=qd['pre_fix']
def _f(a): return f"{a['match']}/{a['n']}"
o.append('\\subsection{QSAR descriptors against RDKit on approved drugs}')
o.append(f"modules.qsar\\_bench computes its own 2D descriptors from a small SMILES parser, so a QSAR model can be built without a chemistry toolkit. We compared them with RDKit {qd['reference'].split()[-1]} on the {qd['n_molecules_rdkit_parsed']} ChEMBL phase-4 molecules RDKit reads. Before the fix the parser rejected {qp['parse_failures']} of them: every SMILES with a / or \\textbackslash{{}} stereo bond (88 molecules, including tamoxifen and diethylstilbestrol) and every sodium, potassium or silver salt (22). On the {qp['n_scored']} it did read, molecular weight matched in {_f(qp['agreement']['molecular_weight'])} (charged bracket atoms such as the [O-] of a nitrate got an implicit hydrogen), rotatable bonds in {_f(qp['agreement']['rotatable_bonds_heuristic'])} (the rule subtracted the ring rank from all non-terminal single bonds, so ring bonds counted as rotors: nicotine got 4 instead of 1) and fraction sp$^3$ in {_f(qp['agreement']['fraction_csp3'])} (carbonyl and alkene carbons counted as sp$^3$). All four are fixed (sugarcode {qd['post_fix_sugarcode_commit']}): the parser reads directional bonds and common counter-ions, bracket atoms carry only their written hydrogens, a bond is rotatable only if it is single, acyclic, between non-terminal atoms and not next to a triple bond, and sp$^3$ carbons are non-aromatic carbons with only single bonds. Now all {qd['n_scored']} molecules parse and molecular weight, heavy atoms, heteroatoms, formal charge, ring rank, rotatable bonds and fraction sp$^3$ agree on {_f(qa['molecular_weight'])} each; donors agree on {_f(qa['hbd_heuristic'])} (the miss is a dihydrate whose water RDKit does not count). Rotatable bonds match RDKit's NonStrict definition; RDKit's default Strict count, which also drops amide C--N bonds, agrees on {_f(qd['rotatable_vs_rdkit_default_strict'])}. The acceptor count stays a labelled heuristic ({_f(qa['hba_heuristic'])} against RDKit's Lipinski acceptors) and should not be read as Lipinski HBA.")
o.append('\\paragraph{(F67) Ring bond test.} A bond $(i,j)$ lies on a ring iff $j$ is reachable from $i$ in $G\\setminus\\{(i,j)\\}$; the number of independent rings is the cyclomatic number $r=|E|-|V|+c$ for $c$ connected components, which counts rings but not ring bonds.')
qm=json.load(open(B+'sweep_qsar_morgan.json'))
o.append(f"The module's Morgan fingerprint is meant to follow ECFP. Its starting atom label used only hydrogens written inside brackets, so CH$_3$, CH$_2$ and CH carbons, and ring and chain atoms, began with the same identifier. On {qm['n_pairs']:,} random pairs of {qm['n_molecules']} drugs its Tanimoto similarities ranked with RDKit's radius-2, 2048-bit Morgan at Spearman {qm['pre_fix']['spearman_tanimoto']}, and the nearest neighbour agreed for {qm['pre_fix']['nearest_neighbour_agree']}/{qm['n_molecules']} molecules. The label now uses RDKit's default invariants (element, heavy degree, total hydrogens, charge, ring membership; sugarcode {qm['sugarcode_commit']}): Spearman {qm['spearman_tanimoto']}, nearest neighbour {qm['nearest_neighbour_agree']}/{qm['n_molecules']}, mean absolute Tanimoto difference {qm['mean_abs_tanimoto_diff']}. The bits are not identical to RDKit's (different hashing, no removal of duplicate environments), so fingerprints from the two should not be mixed in one model.")
o.append('\\paragraph{(F68) Tanimoto on bit vectors.} For fingerprints $a,b\\in\\{0,1\\}^L$, $T(a,b)=\\dfrac{|a\\wedge b|}{|a|+|b|-|a\\wedge b|}$; two fingerprint schemes are compared by the rank correlation of $T$ over sampled pairs and by agreement of each molecule\\textquotesingle{}s arg-max neighbour.')
pp=json.load(open(B+'sweep_acmg_erepo_per_panel.json'))['per_panel']
nb=sum(1 for x in pp if x[2]>x[3]); nr=sum(1 for x in pp if x[3]>x[2]); nt=len(pp)-nb-nr
o.append(f"Split by expert panel (Table~\\ref{{tab:vcep}}), the point model reproduces more calls than the 2015 rules for {nb} of {len(pp)} panels, fewer for {nr} and the same for {nt}. The rules do better for these panels: {'; '.join(x[0].replace(' VCEP','') for x in pp if x[3]>x[2])}. We did not check why against each panel's written specification; for these panels a user should read the module's class next to the rule-based one.")
o.append('\\begin{table}[p]\\centering\\footnotesize\\begin{tabular}{lrrr}\\hline expert panel & variants & point model & 2015 rules\\\\\\hline')
for x in pp:
    nm=x[0].replace('&','\\&'); o.append(f"{nm} & {x[1]} & {x[2]} & {x[3]}\\\\")
o.append('\\hline\\end{tabular}\\caption{Panel calls reproduced by the Bayesian point model and by the ACMG/AMP 2015 combining rules, per ClinGen expert panel (benchmarks/sweep\\_acmg\\_erepo\\_per\\_panel.json).}\\label{tab:vcep}\\end{table}')
ev=json.load(open(B+'sweep_evofold_anm.json'))
o.append('\\subsection{Elastic network modes: a doubled Hessian diagonal}')
o.append(f"modules.evofold\\_4d.anm\\_modes computes anisotropic network model (ANM) modes from C$\\alpha$ coordinates; its fluctuation profile is offered as a B-factor proxy and feeds hinge detection. We built the ANM Hessian for the first chain of all {ev['n_structures']} PDB structures in our set with ProDy {ev['reference'].split()[1]} (cutoff 10\\,\\AA, $\\gamma=1$; ProDy's own eigen-solver fails with the installed SciPy, so both Hessians were diagonalised with numpy). Before the fix no structure matched: the module looped over ordered residue pairs and subtracted each contact block from both diagonal blocks on both visits, so every diagonal block was doubled, rows of the Hessian no longer summed to zero and the six rigid-body zero modes disappeared. The `lowest modes' it reported were therefore not the collective motions of the protein; the fluctuation profile correlated with ProDy's at $r$ as low as {ev['pre_fix']['min_fluct_r']:.2f}, and with crystallographic B-factors at median {ev['pre_fix']['median_bfactor_r']:.2f}. Each contact is now added once (sugarcode {ev['sugarcode_commit']}). All {ev['n_freq_match_at_4dp']}/{ev['n_structures']} structures now give ProDy's six lowest non-zero frequencies to the module's four reported decimals, with fluctuation profiles correlated at $r\\ge{ev['min_fluct_r']:.4f}$; the median B-factor correlation is {ev['median_bfactor_r']:.2f}, the same as ProDy's ({ev['median_bfactor_r_prody']:.2f}). {ev['n_with_extra_zero_modes']} chains have more than six zero modes because of chain breaks; the module skips all zero modes, which is the right behaviour.")
o.append('\\paragraph{(F69) ANM Hessian.} For contacts $r_{ij}<r_c$ with unit vector $\\hat e_{ij}$, $H_{ij}=-\\gamma\\,\\hat e_{ij}\\hat e_{ij}^{\\top}$ for $i\\ne j$ and $H_{ii}=-\\sum_{j\\ne i}H_{ij}$, so each block row sums to zero and $H$ has six zero eigenvalues (three translations, three rotations) for a connected network; mean-square fluctuations are $\\langle\\Delta r_i^2\\rangle\\propto\\sum_{k}\\lVert u_k^{(i)}\\rVert^2/\\lambda_k$ over non-zero modes.')
sa=json.load(open(B+'sweep_sasa_freesasa_recheck14.json'))
o.append('\\subsection{Solvent-accessible surface area against FreeSASA}')
o.append(f"modules.structural\\_biophysics.shrake\\_rupley has its own Shrake--Rupley routine for per-atom and per-residue solvent-accessible surface area (SASA, 960 points per atom), separate from the bio.structures SASA checked earlier. We parsed {len(sa['rows'])} PDB structures from our set ({min(r['n_atoms'] for r in sa['rows'])}--{max(r['n_atoms'] for r in sa['rows'])} protein heavy atoms) with the module's own parser and gave the same atoms and radii to FreeSASA's Lee--Richards algorithm (100 slices, probe 1.4\\,\\AA), a different numerical method. Total SASA agreed within {100*sa['max_total_rel_diff']:.2f}\\% for every structure, and per-residue areas correlated at $r\\ge{sa['min_residue_r']}$ with a mean absolute difference of about 0.3\\,\\AA$^2$ per residue. No bug. The module's Vina-style score is checked in the next subsection; its pose refinement is not yet validated.")
o.append('\\paragraph{(F70) Shrake--Rupley estimate.} Atom $i$ with expanded radius $R_i=r_i+r_p$ carries $N$ near-uniform sphere points $x_{ik}$; its area is $A_i=4\\pi R_i^2\\,\\frac{1}{N}\\sum_k\\mathbf{1}\\big[\\lVert x_{ik}-c_j\\rVert\\ge R_j\\ \\forall j\\ne i\\big]$, with sampling error $O(N^{-1/2})$ per atom that largely cancels in residue and molecule totals.')
vs=json.load(open(B+'sweep_vina_score.json'))
o.append('\\subsection{Vina-form docking score against AutoDock Vina}')
o.append(f"The same module's vina\\_score claims the AutoDock Vina 1.1 functional form on a fixed pose. Reading Vina's source showed three departures. It measured surface distances with Bondi radii (C 1.70, N 1.55, O 1.52\\,\\AA) where Vina uses its X-Score radii (C 1.9, N 1.8, O 1.7, S 2.0\\,\\AA); it counted sulfur as hydrophobic, which Vina does not; and it added $w_{{rot}}N_{{rot}}$ to the energy, whereas Vina divides the intermolecular energy by $1+w_{{rot}}N_{{rot}}$. To test the pair terms numerically with no atom-typing ambiguity we scored stacked all-carbon rings, where every atom is a Vina hydrophobic carbon, with AutoDock Vina {vs['reference'].split()[2]} in score-only mode. Before the fix the module gave {vs['pre_fix']['rows_3.6_4.0_4.6'][0]}, {vs['pre_fix']['rows_3.6_4.0_4.6'][1]} and {vs['pre_fix']['rows_3.6_4.0_4.6'][2]} kcal/mol at 3.6, 4.0 and 4.6\\,\\AA\\ separation where Vina gives {vs['pre_fix']['vina'][0]}, {vs['pre_fix']['vina'][1]} and {vs['pre_fix']['vina'][2]}. After the fix (sugarcode {vs['sugarcode_commit']}) it matches Vina within {vs['max_abs_diff']:.4f} kcal/mol at all {len(vs['rows'])} separations from 3.4 to 6.0\\,\\AA; the residual is Vina's grid interpolation and three-decimal output. The rotor division is checked against the source only. Element-level typing still cannot separate polar from apolar carbon or place donors without hydrogens, so on real complexes the score remains an approximation, as the module says.")
o.append('\\paragraph{(F71) Vina score.} With surface distance $s_{ij}=r_{ij}-R^{XS}_i-R^{XS}_j$, $e=\\sum_{ij}\\big[w_1e^{-(s/0.5)^2}+w_2e^{-((s-3)/2)^2}+w_3\\,s^2\\mathbf 1[s<0]+w_4h(s)+w_5b(s)\\big]$ over pairs within 8\\,\\AA, and $\\Delta G=e/(1+w_{rot}N_{rot})$ with $w=(-0.0356,-0.0052,0.840,-0.0351,-0.587)$, $w_{rot}=0.0585$; $h$ is 1 for $s<0.5$ falling to 0 at 1.5, $b$ is 1 for $s<-0.7$ falling to 0 at 0.')
me=json.load(open(B+'sweep_molecule_eval.json'))
o.append('\\subsection{Library-evaluation graph keys against RDKit canonical SMILES}')
o.append(f"molecule\\_eval deduplicates generated libraries with an order-invariant graph digest (four rounds of Weisfeiler--Lehman relabelling over element, aromaticity and charge, then a sorted edge list) rather than canonical SMILES. A digest like this must give the same key for every SMILES spelling of a molecule and different keys for different molecules. We tested both on {me['n_input']} ChEMBL phase-4 drugs, comparing against RDKit {me['reference'].split()[1]} canonical SMILES with stereochemistry removed, and wrote three randomised SMILES per drug. Before the fix {me['pre_fix']['invariance_failures']} drugs changed key under re-spelling (acetazolamide CHEMBL19 among them). All three were written by ChEMBL with a directional bond marker between two aromatic ring atoms, as in \\texttt{{/N=c1/sc}}. The shared SMILES parser read every / or \\textbackslash{{}} as an explicit single bond, which broke the aromatic ring; RDKit keeps such a bond aromatic. After the fix (sugarcode {me['sugarcode_commit']}), where the marker only sets direction and bond order follows the implicit rule, there are {me['invariance_failures']} invariance failures, {me['key_collisions_distinct_rdkit']} keys shared by molecules RDKit calls different, and {me['rdkit_same_key_split']} RDKit molecules split across keys; both give {me['unique_keys']} unique structures. The directional-bond change left the QSAR descriptor and Morgan benchmarks unchanged when re-run. Internal diversity (mean pairwise Tanimoto distance, radius-2 2048-bit fingerprints, 300 drugs, all pairs) is {me['internal_diversity_sugarcode']} with the module's fingerprint and {me['internal_diversity_rdkit']} with RDKit's. Four WL rounds can in principle merge graphs that differ only beyond radius four; no such case occurred in this set.")
o.append('\\paragraph{(F72) Internal diversity.} For a library of $n$ unique molecules with fingerprints $f_i$, $D=\\binom n2^{-1}\\sum_{i<j}\\big(1-T(f_i,f_j)\\big)$ with $T(a,b)=|a\\wedge b|/(|a|+|b|-|a\\wedge b|)$; the module samples at most $10^4$ pairs and bootstraps a 95\\% interval.')
nu=json.load(open(B+'sweep_nussinov.json'))
o.append('\\subsection{Nussinov folding against an independent implementation, exhaustive oracle and ViennaRNA}')
o.append(f"riboswitch uses an exact Nussinov dynamic program (maximum number of nested base pairs, minimum loop {3}) to score designed switches. We checked the recursion three ways. On {nu['n_oracle']} short sequences (length up to 16) we enumerated every non-crossing matching by brute force; the module matched the exhaustive optimum on all {nu['n_oracle']} (the oracle itself needed two fixes during the check - reused positions and a stale pruning bound - which is why we keep it in the repository). On {nu['n_real']} real Rfam seed sequences from four riboswitch families (TPP RF00059, FMN RF00050, glycine RF00504, cobalamin RF00174), an independently written Nussinov recurrence (pair-$i$-with-$k$ decomposition instead of the module's bifurcation form) agreed on the optimal pair count for all {nu['n_real']} (0 mismatches). Against ViennaRNA {nu['reference'].split()[-2]} minimum-free-energy folds the median base-pair F1 is {nu['f1_vs_vienna_median']} (family means {nu['f1_vs_vienna_by_family']['RF00050']} FMN to {nu['f1_vs_vienna_by_family']['RF00504']} glycine), with the module placing {nu['pair_ratio_module_over_vienna_median']}$\\times$ as many pairs: maximising pair count is not the same as minimising free energy, and we do not claim MFE agreement. The module's estimated\\_energy\\_kcal\\_mol field (-3 per GC pair, -2 per AU/GU) is a heuristic ranking score, not a thermodynamic energy; designs needing energies should go through ViennaRNA, as in the rna\\_nussinov module check.")
o.append('\\paragraph{(F73) Nussinov recursion.} $N_{ij}=\\max\\{N_{i+1,j},\\,N_{i,j-1},\\,\\max_{k>i+m,\\,(s_i,s_k)\\in\\mathcal P}[1+N_{i+1,k-1}+N_{k+1,j}]\\}$ with pair set $\\mathcal P=\\{AU,UA,GC,CG,GU,UG\\}$ and minimum loop $m=3$; the module evaluates the equivalent bifurcation form $N_{ij}=\\max\\{N_{i+1,j},N_{i,j-1},[j-i>m](s_i,s_j)+N_{i+1,j-1},\\max_{i<k<j}(N_{ik}+N_{k+1,j})\\}$.')
pd=json.load(open(B+'sweep_prime_design.json'))
o.append('\\subsection{Prime-editing guide design against published, validated pegRNAs}')
o.append(f"prime\\_design builds pegRNAs: a 20-nt spacer, a 3' extension of reverse-transcription template (RTT) plus primer-binding site (PBS). Three departures from the published anatomy were found by replaying two experimentally validated pegRNAs through the module. (i) The PBS was reverse-complemented out of the RT-template region, so PBS and RTT overlapped; the PBS must anneal to the 3' flap of the nicked strand, i.e. it is the reverse complement of the protospacer's PAM-proximal end. (ii) For plus-strand PAMs the RTT started at the edit, not at the nick. (iii) When the RT template was truncated to the chosen length, the module kept the nick-distal end; reverse transcriptase reads from the PBS, so the RTT's 3' end must pair with the nick base. After the fixes (sugarcode {pd['sugarcode_commit']}) the module reproduces both published extensions exactly: HEK3 +1 CTT insertion (Anzalone et al. 2019; Addgene 132778; also validated by pegFinder, Chow et al. 2021) RTT \\texttt{{TCTGCCATCAAAGC}} + PBS \\texttt{{GTGCTCAGTCTG}}, and RNF2 +5 G$>$T RTT \\texttt{{AACGAACACATCAGG}} + PBS \\texttt{{TAATGACTAAGATG}}. Before the fix the 'PBS' came out as \\texttt{{TCTGCCATCAAA}} - RTT sequence, not flap. End to end, from the HEK3 genomic context (Anzalone substrate AVA024) with the +1 CTT edit, the top design uses the published spacer and a PBS from the correct flap (10 nt auto-chosen by the Wallace-$T_m$ rule vs the published 12 nt; same annealing tract), and its RTT contains the published template at the nick. A crash on insertion edits with empty ref was fixed along the way. The PBS/RTT boundary convention (spacer positions 17/18, one nt PAM-proximal of the canonical Cas9 nick) was adopted to match every published validated pegRNA we could locate, including Anzalone's own in-vitro pegRNAs.")
o.append('\\paragraph{(F74) pegRNA extension.} Spacer $g=g_1\\dots g_{20}$ with PAM at positions 21-23; PBS $=\\overleftarrow{g_{17-L}\\dots g_{16}}$ (length $L\\in[10,16]$, chosen to bring Wallace $T_m=2N_{AT}+4N_{GC}$ near 32\\,\\textdegree C); RTT $=\\overleftarrow{e_{n+1}\\dots e_{n+\\ell}}$ for edited strand $e$, nick at $n$, $\\ell\\in[10,20]$; extension $=$ RTT\\,\\textbullet\\,PBS appended 3\' of the scaffold.')
sp=json.load(open(B+'sweep_stability_promoter.json'))
o.append('\\subsection{Hill occupancy, burst noise and Wright-Fisher drift against theory}')
o.append(f"Two modules were checked at the formula level. promoter\\_lib's thermodynamic occupancy agrees with the Hill form $1/(1+(K_d/c)^h)$ to {sp['hill_max_abs_diff']:.1e} over a grid of Hill coefficients, $K_d$ and concentrations (half-occupancy at $c=K_d$ holds exactly; the $h=1$ case also matches a logistic/\\texttt{{expit}} evaluation to {sp['hill_expit_max_diff']:.1e}), and its expression-noise summary matches Poisson-burst theory ($\\mathrm{{Var}}=\\mu(1+B)$, Fano $=1+B$) on all {len(sp['noise_rows'])} tested settings. stability\\_ai's seeded Wright-Fisher simulation of construct loss (per-generation plasmid-loss and mutation terms, then viability selection $f' = a(1-s)/(1-as)$ with $a=f(1-L-m)$, binomial resampling) tracks an independently written deterministic recursion within {max(r['max_abs_diff_vs_deterministic'] for r in sp['wf_rows'])} at population $2\\times10^6$ across plasmid and genomic constructs, is reproducible under a fixed seed, and gives the expected extremes (0\\% extinction for a low-burden plasmid, 100\\% for a high-burden toxic one). No bug in either; both are theory checks, so the parameters themselves (loss rates, selection coefficients) remain literature-free defaults and are not validated against experimental stability data - a limitation we state rather than a defect.")
o.append('\paragraph{(F75) Wright-Fisher with loss and selection.} $a_{{g}}=f_g(1-L-m)$, $f_{{g+1}}\\sim\\mathrm{{Bin}}(N,\\,a_{{g}}(1-s)/(1-a_{{g}}s))/N$, with plasmid-loss rate $L=(2\\times10^{-3})(1+4b)$ for burden $b$, mutation $m=10^{-4}\\,k$ for size $k$ kb ($\\times2$ if toxic), selection $s=0.08\\,e$ for expression load $e$.')
fa=json.load(open(B+'sweep_fasta.json'))
o.append('\\subsection{FASTA parsing against Biopython on Rfam seed files}')
o.append(f"bio.fasta was compared with Biopython {fa['reference'].split()[1]} SeqIO on three real Rfam seed-alignment FASTA files (TPP RF00059: {fa['rows'][0]['n']} records, FMN RF00050: {fa['rows'][1]['n']}, glycine RF00504: {fa['rows'][2]['n']}) - {sum(r['n'] for r in fa['rows'])} records in total. Identifiers, full descriptions and sequences agree exactly on every record ({fa['mismatches']} mismatches), the streaming reader agrees with the in-memory parser on all three files, and a write-read round trip over 200 records is lossless. One deliberate difference: Biopython rejects a file that starts with blank lines ('comments at the beginning of the file'), while bio.fasta skips them; we treat this as leniency, not a defect, and record it here.")
o.append('\\paragraph{(F76) FASTA round trip.} For records $r_i=(h_i,s_i)$, write-read gives $\\\\mathrm{parse}(\\\\mathrm{write}(r))=r$ with sequence lines wrapped at width $w$: $\\\\mathrm{write}(r)=\\\\{>\\\\!h_i\\\\}\\\\,\\\\|\\\\,\\\\{s_i[kw:(k+1)w]\\\\}_{k=0}^{\\\\lceil |s_i|/w\\\\rceil-1}$; identity holds for $w=50$ on 200 RF00059 records.')
cr=json.load(open(B+'sweep_crisprater.json'))
o.append('\\subsection{CRISPRater guide-efficacy scores against the author-computed reference scores}')
o.append(f"crisprater vendors the published ten-feature linear model of Labuhn et al. 2018 (NAR 46:1375) with its intercept, coefficients and class thresholds. We scored all {cr['n_sgrnas']} sgRNAs from the paper's Supplementary Table 3 (author-computed CRISPRater scores, PMC5814880) and compared. As vendored, {cr['pre_fix_gc_window_4_14']['mismatches_gt_5e-4']} of {cr['n_sgrnas']} guides mismatched. The cause was the GC feature: the module summed GC over spacer positions 4-14, but the published model uses GC4-13 (Figure 4C of the paper; the narrower window also avoids double-counting position 14, which is its own negative feature). After the fix (sugarcode {cr['sugarcode_commit']}) the module matches the authors' scores on {cr['n_sgrnas']-cr['post_fix']['mismatches_gt_5e-4']} of {cr['n_sgrnas']} guides ({100*cr['post_fix']['match_fraction']:.2f}\\%) within 5$\\\\times$10$^{{-4}}$. The three residual outliers each differ from the published model by about one feature weight (exactly one weight in two cases), consistent with isolated anomalies in the supplementary table itself, which also contains two duplicate sequences; we document them rather than fit to them. Class thresholds (low $<$0.56, high $>$0.74) were confirmed against the paper text.")
o.append('\\paragraph{(F77) CRISPRater score.} $s=0.6505037+0.14177\\\\,\\\\mathrm{GC}_{4\-13}+0.06966\\\\,[b_{20}{=}G]+0.04216\\\\,[b_3{\\\\in}\\\\{A,T\\\\}]+0.03303\\\\,[b_{12}{\\\\in}\\\\{A,G\\\\}]+0.02355\\\\,[b_6{=}G]-0.04746\\\\,[b_4{\\\\in}\\\\{A,T\\\\}]-0.04878\\\\,[b_{18}{\\\\in}\\\\{A,G\\\\}]-0.06982\\\\,[b_5{\\\\in}\\\\{A,C\\\\}]-0.07088\\\\,[b_{14}{=}G]-0.08161\\\\,[b_{15}{=}A]$, with $\\\\mathrm{GC}_{4\-13}$ the GC fraction of spacer positions 4-13.')
om=json.load(open(B+'sweep_omega_stats.json'))
o.append('\\subsection{Platform performance analytics against independent recomputation}')
o.append(f"omega\\_stats aggregates recorded metric observations into dashboards, release comparisons and 51 diagnostics. Every computed quantity was recomputed independently with numpy/statistics on synthetic series (4 modules, accuracy and latency, 30 observations each): per-series mean/standard-deviation/min/max match to the module's rounding ({om['stats_mismatches']} mismatches over {om['stats_series']} series), subnetwork mean-of-means matches, least-squares drift slopes match numpy\\.polyfit exactly ({om['dashboard_slope_mismatches']} mismatches), pass rates use the correct direction per kind (latency $\\le$ target, others $\\ge$; {om['dashboard_passrate_ci_mismatches']} mismatches), bootstrap intervals are seed-deterministic and contain the mean, release-comparison effect sizes match the pooled-variance Cohen form ({om['release_mismatches']} mismatches), and the diagnostics block has exactly {om['diagnostics_count']} entries. The release gate behaved correctly on a planted mixed case: a 5\\% candidate improvement in accuracy with a 5\\% latency regression gates fail. No bug.")
o.append('\\paragraph{(F78) Standardized release effect.} For baseline $a$ and candidate $b$, $d=(\\bar b-\\bar a)/\\sqrt{(s_a^2+s_b^2)/2}$ with population variances; relative improvement is $(\\bar b-\\bar a)/|\\bar a|$, sign-flipped for lower-is-better kinds, and the gate fails when any series drops more than the tolerance (5\\%).')
mb=json.load(open(B+'sweep_microbiome.json'))
o.append('\\subsection{16S diversity statistics against scipy and explicit Gower centering}')
o.append(f"microbiome\\_exp computes per-sample alpha diversity (Shannon, Gini--Simpson, richness, Pielou evenness), a Bray--Curtis beta-diversity matrix on relative abundances, classical PCoA ordination, and permutation-based differential abundance. On a 12-sample synthetic cohort every alpha quantity matches scipy\\.stats\\.entropy and direct forms ({mb['analyze16s_mismatches'] + mb['cohort_alpha_mismatches']} mismatches across both entry points), the Bray--Curtis matrix matches scipy\\.spatial\\.distance\\.braycurtis to {mb['bray_curtis_max_abs_diff']}, and a planted control-enriched taxon is recovered with the correct sign and a significant permutation $p$ ({mb['planted_effect']['log2fc']} log2 fold, $p={mb['planted_effect']['p']:.3f}$; unplanted cohort median $p={mb['null_median_p']:.2f}$). The PCoA had a real bug: the Gower centering subtracted means of the unsquared distances, shifting the leading eigenvalue by {mb['pre_fix_pcoa']['pcoa_eig0_diff']:.2f}. After the fix (sugarcode {mb['sugarcode_commit']}) the first two eigenvalues match an explicit $-\\tfrac12 J D^2 J$ computation to {max(mb['pcoa_eig0_diff'], mb['pcoa_eig1_diff']):.1e}. Disease associations in the module are heuristic flags over a small built-in table, and the module itself reports them as hypotheses, not diagnoses; we did not validate the association table against cohort literature.")
o.append('\\paragraph{(F79) Gower-centered PCoA.} With Bray--Curtis matrix $D$, $G=-\\tfrac12 J D^{\\circ 2} J$ for $J=I-n^{-1}\\mathbf 1\\mathbf 1^{\\top}$; coordinates $U_k\\mathrm{diag}(\\sqrt{\\lambda_k})$ from the top eigenpairs of $G$. Centering must use means of $D^{\\circ 2}$, the elementwise square - using means of $D$ does not double-center the squared matrix.')
rd=json.load(open(B+'sweep_rna_decoder.json'))
pos_near=rd['region_counts_pos']['near-stop CDS']+rd['region_counts_pos']["3'UTR"]; pos_tot=sum(rd['region_counts_pos'].values())
neg_near=rd['region_counts_neg']['near-stop CDS']+rd['region_counts_neg']["3'UTR"]; neg_tot=sum(rd['region_counts_neg'].values())
o.append('\\subsection{m6A site prediction against the SRAMP benchmark and single-nucleotide miCLIP sites}')
o.append(f"rna\\_decoder scores candidate m6A sites by a DRACH motif search weighted by region priors (highest near the stop codon and in the 3'UTR) and a local AU-richness exposure term. We validated it on two independent real datasets. First, motif biology: of {rd['miclip_sites_parsed']} single-nucleotide miCLIP CIMS sites in HEK293 cells (GSE63753, Linder et al. 2015), {100*rd['miclip_drach_fraction']:.1f}\\% match the DRACH consensus the module searches for, and the five most common site 5-mers (GGACT, GGACA, AGACT, GAACT, TGACT) are all DRACH. Second, discrimination: the SRAMP mature-messenger benchmark (Zhou et al. 2016) labels {rd['n_pos']+rd['n_neg']} transcript positions on the {rd['n_transcripts']} transcripts we fetched live from Ensembl (positions are 1-based adenosine coordinates: {rd['pos_base_is_A_1based']} of {rd['n_pos_checked']} positives land on A, vs {rd['pos_base_is_A_0based']} under a 0-based reading). Because the benchmark predates the current Ensembl build, {rd['excluded_annotation_drift']} labels no longer sit at a DRACH-centred A and were excluded, leaving {rd['evaluated_pos']} positives and {rd['evaluated_neg']} negatives. The check found a real defect: with the module's original defaults the whole sequence was treated as coding, so the final 100 nt of any transcript inherited the near-stop prior; scored that way the module achieved AUC {rd['auc_module_score_old_wholetx_default']}, below its own exposure feature alone ({rd['auc_exposure_baseline']}). The default now auto-detects the coding region from the first ATG (AUC {rd['auc_module_score']}), and with true Ensembl CDS coordinates the module reaches AUC {rd['auc_module_score_with_cds']} on {rd['evaluated_cds_pos']} positives and {rd['evaluated_cds']-rd['evaluated_cds_pos']} negatives over {rd['cds_aligned_transcripts']} CDS-aligned transcripts. The regional prior direction is validated by the data: {pos_near} of {pos_tot} positives ({100*pos_near/pos_tot:.1f}\\%) fall in near-stop CDS or 3'UTR against {neg_near} of {neg_tot} negatives ({100*neg_near/neg_tot:.1f}\\%), the established m6A topology. This remains a heuristic scorer, far below trained predictors, and the m5C/psi/m1A motif maps are placeholders the module itself flags; we report the AUCs, not a discovery.")
o.append('\\paragraph{(F80) m6A site score.} $s=0.55\\,r+0.45\\,(1-\\mathrm{GC}_{31})$ with region prior $r\\in\\{0.35\\,(5\\prime\\mathrm{UTR}),\\,0.55\\,(\\mathrm{CDS}),\\,0.85\\,(<100\\,\\mathrm{nt\\,from\\,stop}),\\,0.75\\,(3\\prime\\mathrm{UTR})\\}$ over a 31-nt flank; sites are DRACH occurrences, modification at the central A. Discrimination is measured by Mann--Whitney AUC $=\\big(\\sum_{i\\in\\mathrm{pos}}R_i-P(P{+}1)/2\\big)/(PN)$ with midranks $R_i$.')
em=json.load(open(B+'sweep_evidence_mining.json'))
o.append('\\subsection{Live evidence mining against PubMed E-utilities and ClinicalTrials.gov}')
o.append(f"evidence\\_mining queries two public APIs - NCBI E-utilities (esearch then efetch) and the ClinicalTrials.gov v2 studies endpoint - and normalises both into one evidence table. We replayed its traffic against independent live calls made seconds apart with the same query ({em['query']!r}, limit {em['limit']} per source). The module's PubMed identifiers match the independent esearch idlist exactly and in order ({em['pmid_set_overlap']}/{em['n_pubmed']}), its trial identifiers match the independent v2 call exactly and in order ({em['nct_set_overlap']}/{em['n_trials']}), the record\\_count field equals the emitted table length, all PubMed URLs are correctly formed, all PMIDs are numeric, all trial IDs are well-formed NCT identifiers, and {em['titles_nonempty']} of {em['record_count_field']} records carry a non-empty title. Failure semantics are as documented: strict mode is fail-closed (an offline cache miss raises), non-strict mode returns both source errors in-band with zero records rather than silently discarding a failed source, and offline replay from the content-addressed cache reproduces the live record order exactly. No bug. This validates transport, parsing and bookkeeping; it does not validate the mined effect-direction/sample-size text heuristics, which remain unverified extraction guesses.")
o.append('\\paragraph{(F81) Evidence-table merge.} Records $r=(s,i,t,u,d)$ with source $s\\in\\{\\mathrm{PubMed},\\mathrm{CTG}\\}$, identifier $i$, title $t$, URL $u$, date $d$; $\\mathrm{mine}(q)=\\{r\\}_{s,i}$ with $\\mathrm{record\\_count}=|\\mathrm{mine}(q)|$, strict mode $\\Rightarrow$ any source error aborts, non-strict $\\Rightarrow$ errors $\\subseteq$ result. Verified: $i_{\\mathrm{PubMed}}^{\\mathrm{module}}=i_{\\mathrm{PubMed}}^{\\mathrm{esearch}}$ and $i_{\\mathrm{CTG}}^{\\mathrm{module}}=i_{\\mathrm{CTG}}^{\\mathrm{v2}}$ elementwise on 10+10 live records.')
rn=json.load(open(B+'sweep_rarenet.json'))
rnd=rn['diseases']
ex=sum(round(v['match_fraction']*4) for v in rnd.values()); sy=sum(round(v['match_fraction_with_synonyms']*4) for v in rnd.values())
pairs=sum(1 for v in rnd.values() if v['gene_disease_pair_in_hpo'])
o.append('\\subsection{Rare-disease signatures against the HPO annotation corpus}')
o.append(f"rarenet\\_ai ranks six rare diseases from symptom sets, variants and omics over a curated table of symptom signatures, causal genes and prevalences. We audited the table against the Human Phenotype Ontology gene-to-phenotype corpus ({rn['hpo_rows_total']:,} gene--phenotype--disease rows, current release). The audit found one stale curation: Gaucher disease was keyed to the retired gene symbol GBA, which appears nowhere in the current corpus - any gene-keyed lookup would silently miss it; the current symbol GBA1 restores the mapping. After the fix, all {pairs}/6 gene--disease pairs are confirmed (CFTR--OMIM:219700, HTT--143100, FBN1--154700, PAH--261600, GBA1--230800, DMD--310200), and of the 24 curated symptoms {ex} match the disease's annotated HPO term names directly while {sy} match once clinical synonyms are applied (lens dislocation = Ectopia lentis, poor growth = Failure to thrive, calf hypertrophy = Calf muscle hypertrophy). The three residue are annotation absences in this HPO release, not curation errors: no adult-onset row for HTT/OMIM:143100, no musty-odor row for PAH/OMIM:261600, no fatigue row for GBA1/OMIM:230800. Behaviourally, the module ranks the correct disease first for all {rn['diagnose_top1_full_signature']}/{rn['diagnose_top1_of']} complete signatures. Limitations recorded: the symptom vocabulary is lay-oriented, the prevalence fields are unverified literature defaults, and six diseases is a demo-scale table.")
o.append('\\paragraph{(F82) Signature score.} $c=\\min\\{0.99,\\,\\min(1,\\,0.25\\,|S\\cap S_d|+0.1\\sum_{s\\in S\\cap S_d}f(s)^{-1})+0.4\\,[g_d\\in V]+0.15\\,[g_d\\in O]\\}$ for input symptoms $S$, disease signature $S_d$, causal gene $g_d$, variant genes $V$, omics-disrupted genes $O$, and symptom-frequency weight $f$; candidates rank by $c$. Table audit: $g_d$ must appear in the HPO corpus under the OMIM identifier of the disease.')
onc=json.load(open(B+'sweep_oncocircuit.json'))
P=onc['promoters']
o.append('\\subsection{Tumour-promoter selectivity table against Human Protein Atlas pathology data}')
o.append(f"oncocircuit designs tumour-selective kill circuits over a five-entry promoter table with cancer associations and numeric tumour-selectivity values. We audited the table against the Human Protein Atlas v23 pathology resource (403,241 gene--cancer patient-sample rows). PSA/KLK3 is confirmed outright: detected in all ten prostate-cancer samples and in none of the 89 samples across the other 19 cancers (detection and High-expression shares in the claimed cancer both 1.0). AFP holds at High-expression level (liver is the maximum-High cancer; High share in claimed tissue {P['AFP']['high_share_in_claimed']}), although low-level AFP detection is pan-cancer. HER2/ERBB2 is directionally right with breast the maximum-High cancer ({P['HER2_inducible']['high_rate_claimed']['breast cancer']} High rate) and gastric much weaker ({P['HER2_inducible']['high_rate_claimed']['stomach cancer']}) than the table implies. Two entries do not survive as written: Survivin/BIRC5 is near-ubiquitous across tumours (breast 1.0, lung 0.917, colorectal 0.917 detection; its High expression concentrates in testis), so it works as a proliferation-associated second input but its 0.80 selectivity figure is unsupported; and hTERT/TERT protein is essentially undetectable by immunohistochemistry in every cancer, so the pan-cancer hTERT claim - which rests on promoter-reactivation and promoter-mutation biology, not protein abundance - can be neither confirmed nor refuted with this evidence class. The circuit behaviour itself is internally consistent: the dual-input AND design expresses the payload at {onc['dual_sim']['output_tumor']} in tumour against {onc['dual_sim']['output_normal']} in normal and {onc['dual_sim']['output_single_positive']} in single-positive tissue, while the single-input comparator leaks (single-positive equals tumour output). We kept the table's selectivity numbers as uncalibrated literature-free defaults and recorded the evidence class each claim actually needs.")
o.append('\\paragraph{(F83) Detection specificity.} For gene $g$ and claimed cancer set $C$, $\\mathrm{detshare}=\\sum_{c\\in C}\\mathrm{det}_{g,c}/\\sum_{c}\\mathrm{det}_{g,c}$ with $\\mathrm{det}=n_{\\mathrm{High}}+n_{\\mathrm{Med}}+n_{\\mathrm{Low}}$ per HPA patient counts; PSA/KLK3 attains 1.0. Dual-input gate: payload $\\propto\\prod_i a_i$ vs single-input $\\propto a_1$; selectivity requires output in single-positive tissue $\\ll$ tumour.')
d2c=json.load(open(B+'sweep_dna_to_code.json'))
o.append('\\subsection{Educational DNA-to-code utilities against Ensembl proteins and consequence rules}')
o.append(f"dna\\_to\\_code maps molecular-biology concepts to code analogies and exposes small executable helpers. We ran the helpers on {d2c['translation']['n']} real mouse Ensembl coding sequences. Translation reproduced the Ensembl protein exactly for {d2c['translation']['exact']} of {d2c['translation']['n']} transcripts, and the codon table matched NCBI translation table 1 on all 64 codons. The mutation helper had a real gap: it only reported silent and nonsense flags, so start-codon and stop-codon substitutions were silently lumped with missense changes. On {d2c['vep']['n_submitted']} real substitutions the old flags agreed with Sequence Ontology consequence terms on {d2c['vep']['legacy_flags_agree']}; every start-lost and stop-lost change was misreported. The fixed helper returns a consequence term and agrees on {d2c['vep']['agree']} of {d2c['vep']['n_scored']}. A second error sat in the teaching snippet for transcription, which swapped T for U on the template strand; on real cDNAs that gives {d2c['template_strand']['old_TtoU_on_template_matches_mRNA']} of {d2c['template_strand']['n']} correct mRNAs, against {d2c['template_strand']['revcomp_snippet_matches_mRNA']} of {d2c['template_strand']['n']} for the corrected reverse-complement form. Negative note: the Ensembl VEP service returned server errors throughout the run, so the reference classifier is an independent Biopython codon-level implementation of the same rules, not VEP itself.")
o.append('\\paragraph{(F84) Codon-level consequence.} For substitution at CDS position $p$ (0-based), codon index $k=\\lfloor p/3\\rfloor$, reference codon $r$ and mutant codon $m$ with $a=T(r)$, $b=T(m)$ under table $T$: start\\_lost if $k=0\\wedge r=\\mathrm{ATG}\\wedge m\\neq\\mathrm{ATG}$; stop\\_lost if $a={*}\\wedge b\\neq{*}$; stop\\_retained if $a=b={*}$; stop\\_gained if $b={*}$; synonymous if $a=b$; else missense. Template identity: $\\mathrm{mRNA}=\\overline{\\mathrm{rev}(t)}$ with $A\\to U$, i.e. the coding strand with $T\\to U$.')
dti=json.load(open(B+'sweep_dti_bench.json'))
o.append('\\subsection{Proteochemometric drug--target baseline against live ChEMBL and UniProt}')
w=dti['warm_random']; csp=dti['cold_target']; ts=dti['time_split']
o.append(f"dti\\_bench trains a target-conditioned ridge model over ligand fingerprints, protein composition and explicit interaction terms, and ingests exact-relation pChEMBL pairs from the live ChEMBL API. The audit found that the ingestion client could never succeed on the live API: it read component sequences inline from the target resource, which embeds no sequences, so every call raised before any data was retrieved. The fixed client fetches the component resource and fails closed on multi-component targets. On six kinases it retrieved {sum(dti['targets'].values()):,} exact-relation records; all six target sequences match UniProt canonical exactly, and the median aggregation reproduces {dti['median_aggregation']['agree']} of {dti['median_aggregation']['checked_molecules']} independently recomputed molecule medians. On the pooled real set a warm-random split gives RMSE {w['model_rmse']:.3f} against {w['naive_mean_rmse']:.3f} for a naive-mean baseline ($R^2$ {w['model_r2']:.3f}, seed-deterministic split, all {w['inside_ad']} test records inside the applicability domain). A chronological split degrades to $R^2$ {ts['r2']:.3f}, and a cold-target split holding out ABL1 and EGFR collapses to $R^2$ {csp['r2']:.3f} - but the module's applicability gate flags all {csp['outside_ad']} of those predictions as outside-domain, which is the intended honest behaviour for a composition baseline. Ligand similarity rank-agrees with the RDKit Morgan generator (Spearman {dti['tanimoto_vs_rdkit']['spearman']:.3f} over {dti['tanimoto_vs_rdkit']['n_pairs']:,} pairs). Caveat: the year-granularity time split lets the boundary year straddle train and test.")
o.append('\\paragraph{(F85) Cold-start applicability gate.} Ridge on standardised features $z$: $\\hat y=b+\\sum_j\\beta_j z_j$, $\\beta=(Z^{\\top}Z+\\alpha I)^{-1}Z^{\\top}y$. Applicability: inside iff $\\max_{s\\in T}\\mathrm{Tan}(f(x),f(s))\\ge 0.35$ and $\\max_{q\\in Q}\\mathrm{pid}(p,q)\\ge 0.30$ with positional identity $\\mathrm{pid}=n^{-1}\\sum_i[p_i=q_i]$. Cold-target holdout: $R^2=-0.883$ with 405/405 flagged outside.')
md=json.load(open(B+'sweep_mutdock.json'))
o.append('\\subsection{Mutation docking against Platinum experimental affinity changes}')
o.append(f"mutdock predicts how a point mutation in a binding pocket changes small-molecule binding. We validated it against the Platinum database of experimentally measured affinity changes (1,008 single-point records). For {md['scored']} entries we rebuilt the true binding pocket from the fetched wild-type PDB structure (residues within 6 A of the ligand) and compared against $\\Delta\\Delta G=RT\\ln(K_{{mt}}/K_{{wt}})$. Direction is right in {md['sign_accuracy']*100:.1f}\\% of cases, but the rank correlation with experiment is only {md['spearman_exp_vs_module']}. The cause is visible in the predictions: the docking rescore is composition-based, so a same-class substitution leaves it unchanged and the output collapses onto the class-penalty table. Auditing that table on {md['class_table_audit']['n_entries']} Platinum entries shows every covered class pair has the correct sign, since binding-site mutations hurt binding on average, but the magnitudes are miscalibrated and five of sixteen pairs use an undocumented default. We kept the table and documented the gap rather than refit it to the validation data. Formula checks pass: the reported fold-change equals $e^{{\\Delta\\Delta G/0.593}}$ exactly.")
o.append('\\paragraph{(F86) Mutation $\\Delta\\Delta G$ heuristic.} $\\Delta\\Delta G=0.6\\,(G_{mt}^{dock}-G_{wt}^{dock})+0.4\\,P(c_{wt}\\to c_{mt})$ with class-penalty table $P$; fold-change $=e^{\\Delta\\Delta G/RT}$, $RT=0.593$ kcal/mol at 298 K. Platinum audit: $\\mathrm{sign}$ correct for 11/11 covered pairs; Spearman $\\rho=0.036$.')
bm=json.load(open(B+'sweep_bio_material.json'))
o.append('\\subsection{Biomaterial degradation model against its own reported half-lives}')
o.append(f"bio\\_material designs production and predicts degradation for four biomaterials. The audit found an internal contradiction: the degradation curve decayed with half-life $1/k$ while the reported half-life was $\\ln 2/k$ (for PHA in soft tissue, 42.0 d versus the reported 28.9 d). The fixed module uses the first-order form $M_0e^{{-kt}}$; all {bm['degradation']['n_cases']} material-by-site cases now agree with their reported half-lives and track $e^{{-kt}}$ to within 0.15 percentage points. The remaining physics helpers match independent recomputation: rubber elasticity $G=\\nu RT$, $E=3G(1-p)^2$; Herschel--Bulkley stress; the analytic cosh profile of steady reaction--diffusion (agreement $3.5\\times10^{{-18}}$); and a deterministic polymerization integration. Table audit: PHA modulus and tensile match the Goodfellow PHB datasheet exactly; PLA tensile sits inside the datasheet range while its modulus is 0.3 GPa below it; spider silk matches classic dragline values; bacterial cellulose is unverified. Degradation rates and site factors remain heuristic.")
o.append('\\paragraph{(F87) First-order degradation.} $M(t)=M_0e^{-kt}$, $t_{1/2}=\\ln 2/k$; effective modulus of a porous network $E=3\\nu RT(1-p)^2$. Pre-fix curve used $2^{-kt}$ ($t_{1/2}=1/k$) against a reported $\\ln 2/k$.')
cf=json.load(open(B+'sweep_cell_free_opt.json'))
o.append('\\subsection{Cell-free expression optimizer grid alignment}')
o.append(f"cell\\_free\\_opt grid-searches a Gaussian response surface for cell-free protein synthesis yields. The audit found that the default grid never evaluated the documented optimal template concentration, capping the reported optimum at {cf['bug35_prefix']['yield']} g/L against the model maximum {cf['bug35_prefix']['model_max']} g/L. After the fix the search returns the exact optimum for grid steps 1-4 and agrees with an independent brute-force argmax. Cost, batch normalisation, sensitivity elasticities and Pareto filtering all match independent recomputation. Caveat: the Euler-integrated kinetic trace overshoots the analytic integral (final {cf['kinetics']['final_g_l']} vs {cf['kinetics']['analytic_final']} g/L at 6 h), a declared discretisation.")
o.append('\\paragraph{(F88) CFPS response surface.} $y=2\\prod_i e^{-((x_i-o_i)/w_i)^2}$ g/L over reagents $x_i$ with optima $o_i$ and widths $w_i$; kinetic trace $r(t)=v_{max}e^{-t/\\\\tau}$, cumulative $v_{max}\\\\tau(1-e^{-t/\\\\tau})$; grid must contain $o_i$ for all $i$.')
ct=json.load(open(B+'sweep_car_t_designer.json'))
o.append('\\subsection{CAR-T construct curation against approved products}')
o.append(f"car\\_t\\_designer recommends CAR architectures from curated antigen, scFv and costimulatory tables. Its CD19 recommendation (FMC63, CD8$\\alpha$ hinge, 4-1BB, CD3$\\zeta$) is exactly the Kymriah architecture, and its BCMA recommendation (C11D5.3, CD8$\\alpha$, 4-1BB) matches the Abecma FDA label; the alternative CD28 CD19 product is acknowledged in the rationale. The costimulatory choice rule, safety-switch inclusion, toxicity formula and all helper functions (selectivity ratios, logic gates, exhaustion and killing curves, trial persistence) reproduce independent recomputation. Predicted response for CD19 is {ct['trial']['response_value']}, in a plausible range for the declared class-level heuristic; the module states it is not fitted to per-antigen clinical data.")
o.append('\paragraph{(F89) CAR heuristic scores.} CRS risk $=\\min(0.3+0.2\,e_c,\,0.9)$, off-tumour $=0.15\,|N|$ for costim expansion $e_c$ and normal tissues $N$; exhaustion $E(d)=1-e^{-r d/14}$; kill fraction $=f(1-e^{-\rho R})$ at E:T ratio $R$ with antigen-positive fraction $f$; persistence $p(0.85)^m$.')
bf=json.load(open(B+'sweep_biofactory.json'))
o.append('\\subsection{Biofoundry scheduler against workflow dependencies}')
o.append(f"biofactory\\_1\\_a generates robotic protocols and schedules them. The audit found that the scheduler ignored workflow order: steps started whenever their resource was free, so the golden-gate thermocycle ran at $t=0$ in parallel with its own input dispenses and the reported makespan was {bf['bug36_prefix']['golden_gate_makespan']:.0f} min against the true {bf['bug36_prefix']['sequential']} min. After the fix every step starts at the later of resource-free and predecessor-end; all three workflows now give ordered schedules whose makespan equals the sequential sum (golden-gate {bf['schedules']['golden_gate']['makespan']:.0f}, gibson {bf['schedules']['gibson']['makespan']:.0f}, pcr-screen {bf['schedules']['pcr_screen']['makespan']:.0f} min). The Bayesian condition update, PID trace, reagent half-life compensation, Zhang $Z'$ factor and DAG rerouting all match independent recomputation exactly. Protocol steps sit within standard NEB Golden Gate and Gibson method bounds.")
o.append('\paragraph{(F90) Assay and update identities.} Zhang $Z^\prime=1-3(\sigma_s+\sigma_b)/|\mu_s-\mu_b|$; conjugate update $\pi^{-1}=\pi_0^{-1}+n/\nu$, $\mu=(\mu_0/\pi_0+\sum o_i/\nu)\pi$ for noise variance $\nu$; reagent activity $a=\ell\,2^{-t/t_{1/2}}$ with compensation $1/a$; list schedule $s_i=\max(r_{free},e_{i-1})$.')
md=json.load(open(B+'sweep_metabodesigner.json'))
_yb={x[0]:x[1] for x in md['bug']['before']['yields']}; _ya={x[0]:x[1] for x in md['bug']['after']['yields']}
_ec=md['ec_summary']; _cb=md['carbon_balance_summary']
o.append(r'\subsection{Metabolic pathway designer against KEGG and fermentation stoichiometry}')
o.append(r"metabodesigner searches a curated reaction graph for glucose-to-product routes and scores them with an LP flux model. Every reaction was checked against its KEGG ENZYME record (name and substrate/product compound IDs) and every metabolite formula against KEGG COMPOUND. The audit found that the glycolysis graph had no triose-phosphate isomerase, so the aldolase product DHAP was a dead end and the LP returned %.1f mol lactate and %.1f mol ethanol per mol glucose against the textbook 2. The thiolase step also consumed one acetyl-CoA instead of two, and by cancellation the 3-hydroxybutyrate yield stayed at the correct 1.0. After adding EC 5.3.1.1, a byproduct-recycling closure, the 2:1 thiolase stoichiometry and the PDH CO$_2$, the yields are %.1f, %.1f and %.1f mol/mol; %d of 17 reactions match KEGG exactly, %d are correctly named lumped steps and one has a class-level EC; %d of %d checkable reactions are carbon balanced. The remaining imbalance is citrate synthase, which treats oxaloacetate as a cofactor. Free-energy and kcat defaults are placeholder priors and were not validated." % (_yb['lactate'], _yb['ethanol'], _ya['lactate'], _ya['ethanol'], _ya['3-hydroxybutyrate'], _ec['exact'], _ec['name ok, lumped/abbreviated step'], _cb['balanced'], _cb['balanced']+_cb['unbalanced']))
o.append(r'\paragraph{(F91) Pathway yield by LP.} $\max v_T$ s.t. $S_{int}v=0$, $0\le v\le 1$; molar yield $Y=(Sv)_T/(-(Sv)_{glc})$; carbon balance $\sum_s n_C(s)=\sum_p n_C(p)$ with acyl-CoA counted as $n_C-21$; glycolysis requires $\mathrm{DHAP}\rightleftharpoons\mathrm{GAP}$ for $Y_{lac}=2$.')
bs=json.load(open(B+'sweep_bio_switch.json'))
o.append(r'\subsection{Biosensor design against PubChem descriptors and binding literature}')
o.append(r"bio\_switch couples curated ligand-binding domains to reporters and models dose-response, noise and processing. Its descriptor table was checked against PubChem for all five small-molecule analytes: molecular weights, TPSA and donor counts match, acceptor counts differ only by definition (Lipinski N+O counting versus PubChem's refined rules), and logP values differ by method (clogP versus XLogP3). The audit found that the Lipinski violation count was cast to a boolean, so lactose (two violations: 8 donors, 11 acceptors) was classed moderate instead of low under the module's own rule, and the returned field read True instead of 2. A second curation error put the TetR-tetracycline $K_d$ at 10 nM against the measured $K_a=3\pm2\times10^9$ M$^{-1}$ (0.2-1 nM, Takahashi 1991, PMID 1812784); both are fixed. The fluoride riboswitch $K_d$ of 60 $\mu$M matches the crcB literature exactly; the theophylline aptamer value (0.3 $\mu$M) sits within the 0.1-0.32 $\mu$M literature range. Hill response, tunable-sensor c10/c90 (grid-quantized, 7.94 versus continuous 9.0 for $n=2$), gate logic, temporal filtering, feedback curves and degradation kinetics all reproduce independent recomputation, and the Gillespie simulation converges to the deterministic occupancy (0.1664 versus 0.1667 bound fraction) with seed reproducibility and a correct copies-per-fL conversion. Documented caveats: the reaction-diffusion profile uses a semi-infinite slab ($\exp(-x/\lambda)$) where a finite cell gives flatter cosh profiles, off-target cross-reactivity is an order-of-magnitude proxy, and the remaining curated $K_d$ values are plausible curations, not individually verified.")
o.append(r'\paragraph{(F92) Sensor dose-response and noise.} Hill $R(c)=V_{max}c^n/(K_d^n+c^n)$, threshold ratio $c_{90}/c_{10}=81^{1/n}$; occupancy $\bar b=L/(L+K_d)$ from birth-death propensities $k_{on}L(N-b)$, $k_{off}b$; copies per fL $=6.022\times10^{2}\,C_{\mu M}$; intracellular gradient $c(x)=c_0 e^{-x/\lambda}$, $\lambda=\sqrt{D/k}$.')
dg=json.load(open(B+'sweep_dark_genome.json'))
o.append(r'\subsection{Dark-genome regulatory decoder against JASPAR and UCSC CpG islands}')
o.append(r"dark\_genome decodes the regulatory landscape of non-coding sequence: TF motif hits, enhancer clusters, CpG islands and lncRNA candidates, plus biophysical surrogates. Its eight TF consensus motifs were checked against JASPAR position weight matrices: five match the matrix argmax sequence exactly (AP-1, NF-$\kappa$B, TATA-box, E-box, CCAAT), while p53, GC-box and HNF4 follow the canonical literature consensuses (El-Deiry RRRCWWGYYY, matching the p21/WAF1 site GAACATGTCC; GC-box GGGCGG; HNF4 DR1) that differ from the assay-specific JASPAR versions fetched. The audit found that motif\_binding\_energy credited any base at a degenerate motif position, so R matched C/T: on poly-C with motif RRR the module reported match 1.0 against the true 0.0, and the p53, TATA-box and HNF4 minimum energies on a real promoter were all inflated. After the fix to set-based IUPAC matching all eight energies equal independent recomputation. Against the UCSC cpgIslandExt track on hg38 the module detects both real promoter islands tested (MLH1, CDKN2A) but calls 3 false positives in a 13 kb desert window because it omits UCSC's post-merge length filter; the tradeoff is documented rather than refit. All 64 motif hits reported for the 10 kb MLH1 locus pass an independent IUPAC regex check. The weighted coordinate field, damped graph propagation, nucleosome occupancy, enhancer-gene causality, logic gates, temporal trajectories and the precision-weighted perturbation update all match independent recomputation exactly.")
o.append(r'\paragraph{(F93) Regulatory field and propagation.} Potential $\phi=0.3\,g+0.3\,a+0.25\,h+0.1(1-m)+0.05\min(1,20\rho)$ for GC $g$, ATAC $a$, H3K27ac $h$, methylation $m$ and motif density $\rho$; contacts $w_{ij}=(1+|i-j|)^{-0.8}$; damped propagation $s_{t+1}=(1-\delta)s_0+\delta\,A_{row}^{-1}A\,s_t$; CpG $O/E=n_{CG}N/(n_C n_G)>0.6$ with GC$>0.5$; energy $E=-8\,\mathrm{match}+0.8\,\mathrm{AT\,shape}$ with set-based IUPAC matching.')
cf=json.load(open(B+'sweep_cellfatenet.json'))
o.append(r'\subsection{Cell-fate GRN engine against HGNC and reprogramming cocktails}')
o.append(r"cellfatenet simulates a curated 18-node lineage GRN with Hill dynamics, epigenetic gating and optimal-control reprogramming. Curation checks: 19 of 20 gene symbols are approved HGNC symbols (OCT4 is an alias of POU5F1); the cardiac driver edges cover the full Ieda GMT cocktail (GATA4, MEF2C, TBX5; PMID 20691899), while OSKM lacks KLF4/MYC and the neuronal BAM set lacks POU3F2 (coverage caveats). The audit found two defects. First, production was $\sigma(2s)$, a 0.5 basal floor that left every gene half-expressed with no regulators (quiet TNNT2 steady state 1.43); a thresholded $\sigma(6(s-0.5))$ brings the quiet state to 0.20 with single-driver activation preserved. Second, the optimal-control stack was self-defeating: controls could force structural markers, unspecified targets counted as zeros so driver activation was penalized - the pre-fix fibroblast-to-cardiomyocyte recipe repressed MEF2C and TBX5, the opposite of the GMT protocol - the finite-difference step sat below solver noise, and negative concentrations turned the $x^2$ Hill term into a sign exploit. After restricting controls to transcription-factor nodes, scoring only specified targets, setting $\varepsilon=10^{-3}$ and clamping the Hill input, the cardiac search overexpresses MEF2C and reaches TNNT2 1.98 / MYH6 2.01 with stochastic success 1.0. Deterministic trajectories match an independent integrator to 0.0; the Langmuir chromatin occupancy, noisy-ensemble statistics and attractor stability ($\max|\dot x|=3.1\times10^{-8}$) all check out.")
o.append(r'\paragraph{(F94) Fate dynamics and control.} $\dot x=g\odot\sigma(6(W\phi(x)-0.5))+u-\gamma x$, $\phi(x)=x_+^2/(0.25+x_+^2)$, $\gamma=0.35$; occupancy $=K_a c/(1+K_a c)$ with $K_a=e^{-\Delta G/RT}$; objective $J=\sum_{i\in S}(x_i(T)-t_i)^2+0.08\|u\|_2^2+0.04\|u\|_1$ over specified targets $S$ with controls restricted to TF nodes; success $=e^{-\|x(T)-t\|_S}$.')
bg=json.load(open(B+'sweep_biogpt_lit.json'))
o.append(r'\subsection{Literature knowledge graph against live PubMed, iCite and statsmodels}')
o.append(r"biogpt\_lit builds an evidence-weighted claim graph from the literature: a precision-biased relation extractor, citation/sample-size/replication edge weights, contradiction detection, temporal consensus, multi-hop latent paths, gap prioritization and a DerSimonian-Laird meta-analysis engine. The sweep ingested 8 live PubMed abstracts (query: SIRT1 resveratrol activation, all 2026) through the module's own entrez client and merged NIH iCite citation counts (only one PMID has an iCite record so far; the query returns very recent papers - documented). The audit found one defect: the extractor accepted any token before a relation word as the subject, producing the garbage triple (and, inhibits, Neuronal) from PMID:42746974 - one of four live-extracted claims. A function-word subject filter fixes it; post-fix all three extracted triples are valid ((formulations, activates, SIRT1), (SIRT1, activates, AMPK), (AMPK, inhibits, mTORC1)) and the negation/loss-of-function unit suite passes 7/7. The meta-analysis engine matches statsmodels combine\_effects (DL) to below $10^{-9}$ on fixed effect 0.29756, random effect 0.32299 and $\tau^2=0.08470$. Evidence weights, consensus/confidence, contradiction detection, temporal agreement (0.692), multi-hop path sets, bottleneck path strength (0.515), gap leverage and the update\_validation flip all equal independent recomputation exactly.")
o.append(r'\paragraph{(F95) Evidence weighting and DerSimonian-Laird pooling.} $w=0.3+0.3\min(\log_{10}(1+c)/3,1)+0.25\,\mathbb{1}_{\mathrm{rep}}+0.15\min(n/100,1)$; fixed effect $\bar\theta=\sum w_i\theta_i/\sum w_i$ with $w_i=1/v_i$; $Q=\sum w_i(\theta_i-\bar\theta)^2$; $\tau^2=\max\!\big(0,(Q-(k-1))/(S_1-S_2/S_1)\big)$; random weights $1/(v_i+\tau^2)$; temporal agreement $a_t=w_t^+/(w_t^++w_t^-)$; path strength $=\min_{e\in p}w_e$.')
ga=json.load(open(B+'sweep_gene_analysis.json'))
o.append(r'\subsection{Gene digital twin against NCBI Gene, UniProt, RefSeq and PubMed}')
o.append(r"gene\_analysis profiles a gene locus (composition, longest ORF, regulatory landscape, CRISPR targets, variant interpretation) and merges live NCBI Gene, UniProt, ClinVar and Reactome records. For TP53, BRCA1, CFTR, HBB and EGFR the live profile returned the correct NCBI Gene identifier and chromosome, the Swiss-Prot canonical accession and canonical protein length in 5 of 5 genes. On RefSeq mRNAs NM\_000518.5, NM\_000546.6 and NM\_000492.4 the longest ORF equals the annotated CDS (147, 393 and 1480 residues) and molecular weights agree with Biopython to within $4.2\times10^{-5}$ relative. Publication counts match an independent PubMed query exactly and replicate numbers equal statsmodels NormalIndPower in 4 of 4 designs. Bug 44 was found on real transcripts: HGVS c. coordinates were indexed into the transcript without the 5' UTR offset, and full ClinVar names were parsed from the accession digits, so the sickle variant c.20A$>$T read codon TTC or ACT instead of GAG. After the fix, 6 of 6 clinical hotspots (HBB E7, Q40; TP53 R175, R248, R273; CFTR G551) map to the correct reference base and residue.")
o.append(r'\paragraph{(F96) HGVS coordinate mapping and sample size.} Locus position $p=s_{CDS}+c$ for $c>0$ and $p=s_{CDS}+c+1$ for $c<0$, with $s_{CDS}$ the 0-based start of the longest forward ORF; codon start $s_{CDS}+3\lfloor(p-1-s_{CDS})/3\rfloor$; replicates $n=\lceil 2\sigma^2(z_{1-\alpha/2}+z_{1-\beta})^2/\delta^2\rceil$; Boltzmann populations $p_k=e^{-E_k/RT}/\sum_j e^{-E_j/RT}$ with $RT=0.593$ kcal/mol.')
lb=json.load(open(B+'sweep_liquid_biopsy.json'))
o.append(r'\subsection{Liquid-biopsy stack against TCGA PanCancer and cfDNA fragment literature}')
o.append(r"liquid\_biopsy combines ctDNA calling, a cfDNA fragment-length model, Dirichlet-mixture haplotype EM, tumor architecture assembly and longitudinal tracking. Its tumor-type marker panels were scored against TCGA PanCancer Atlas mutation calls from cBioPortal for six cancers. TP53 was the most frequently mutated checked gene in lung adenocarcinoma (52.1\% of 566 samples) and was mutated in 59.8\% of 179 pancreatic samples, yet was missing from both panels; adding it raised panel coverage from 46.3\% to 76.1\% (lung) and 66.5\% to 74.9\% (pancreatic). Bug 45: haplotype candidates were built by filling unobserved loci with 0, so a haplotype observed only as partial fragments was never a candidate; with truth 111/000 the EM returned 000, 011 and 110. After the fix it returns 111 and 000 at 0.479 each. The fragment model's docstring claimed entropy rises with tumor fraction; the model itself shows entropy peaking near balanced mixtures (4.60 bits at 0.3, 4.55 at 0.6), whereas KL divergence and the 100-150 bp fraction rise monotonically. Anchors match Underhill et al.\ (134-144 bp versus 167 bp).")
o.append(r'\paragraph{(F97) Fragment mixture and haplotype EM.} Gamma component with mode $m$ and spread $s$: $k=1+(m/s)^2$, $\theta=m/(k-1)$; entropy $H=-\sum_b p_b\log_2 p_b$; $D_{KL}(p\|q_h)=\sum_b p_b\log(p_b/q_{h,b})$; fragment likelihood $P(f\mid h)=(1-\epsilon)^{n_o-m}\epsilon^{m}$ over $n_o$ observed loci with $m$ mismatches; update $\pi_j=(\sum_i r_{ij}+\alpha)/(N+\alpha K)$; panel coverage $=|\bigcup_{g\in P}S_g|/N$.')
vo=json.load(open(B+'sweep_vector_opt.json'))
o.append(r'\subsection{AAV capsid engineer against real VP1 sequences and scoring recomputation}')
o.append(r"vector\_opt designs capsid variants by trading receptor-affinity gain against NAb escape and conservation penalties over five variable regions. Its scoring was recomputed exactly from the stated formulas with the module's own random sequence for three seeds, and directed evolution round $r$ equals a fresh engineering run seeded $1+r$. The region annotations were checked against the real capsid sequences of AAV2 (UniProt P03135, 735 residues) and AAV9 (Q6JC40, 736 residues): a global alignment gives 82.3\% identity, and window identity confirms VR-VIII (0.33) and VR-IV (0.43) as the most variable regions. Two annotation limits were found and documented: receptor contact is serotype-dependent (AAV2's heparan-sulfate contact R585/R588 sits inside VR-VIII, PMID 9445046, while the table follows the AAV9 default), and the GH-loop conservation constant 0.35 reflects the loop tip, since the measured identity over the 590-620 span is 0.81.")
o.append(r'\paragraph{(F98) Capsid variant scoring.} Receptor gain $g=0.15\,m\,c_r\,u_1$ with $c_r\in\{1,0.2\}$, $u_1\sim U(0.7,1.3)$; NAb loss $l=0.2\,m\,u_2\,\mathbb{1}_{\mathrm{epitope}}+0.02\,m\,u_2\,(1-\mathbb{1}_{\mathrm{epitope}})$; integrity $I=1-0.08\,m(1-C_r)$; transduction $T=\mathrm{clip}(0.5+g-(1-I),0,1)$; ranking score $0.5\,T+0.5\min(l,1)$; global identity $604/734=0.823$.')
np_=json.load(open(B+'sweep_neuroplan_ai.json'))
o.append(r'\subsection{Neurosurgical planner against an admissible-path oracle}')
o.append(r"neuroplan\_ai plans tumor approaches: corridor scoring over an eloquent-region risk field, weighted A\* pathfinding, MRI segmentation, tractography clearance and a NeuroTwin resection simulator. The corridor algebra, NeuroTwin probabilities, segmentation threshold and centroid all recompute exactly. Two bugs were fixed. Bug 47: tract clearance was measured to streamline vertices only, so a fiber passing near the tumor between samples was reported 7.30 mm clear when the segment comes within 6.0 mm; clearance is now point-to-segment. Bug 46: the A\* docstring claimed an admissible heuristic, but the frontier uses a 50-fold inflated weight; against an admissible oracle with the identical cost, the returned path cost 640.6 versus the 340.1 optimum (88\% gap) on an oblique entry. The docstring now states the greedy bound, and four dead duplicate definitions were removed. The normalized atlas places brainstem lowest, motor cortex highest and visual cortex most posterior, consistent with anatomy.")
o.append(r'\paragraph{(F99) Risk field, path cost and tract clearance.} $R(p)=\sum_i w_i e^{-d_i^2/2\sigma^2}$, $\sigma=12$; step cost $c=\ell\,(1+\lambda\min(R,1.25))$, $\lambda=8$; frontier $g+50h$; segment clearance $\min_t\|p_0+t(p_1-p_0)-c\|-r$, $t=\mathrm{clip}\!\big(\frac{(c-p_0)\cdot(p_1-p_0)}{\|p_1-p_0\|^2},0,1\big)$; deficit $p=\min(0.95,\,w\,k\,f/(1+\mathrm{clr}/5))$; aggregate $1-\prod(1-p_i)$.')
af=json.load(open(B+'sweep_alpha_fold_ui.json'))
o.append(r'\subsection{Structure predictor against 1UBQ, AlphaFold DB and the 1978 Chou-Fasman rules}')
o.append(r"alpha\_fold\_ui implements Chou-Fasman prediction, idealized backbone building, pocket detection and refinement, and can analyze real structures. On real data: ubiquitin 1UBQ parses to 76 residues with X-ray resolution 1.8 \AA{} and exactly recomputed B-factor statistics; the AlphaFold model of HBB (P68871) has mean pLDDT 97.18 with no low-confidence residues. Bug 48: the helix-extension rule admitted any residue with $P_\alpha>100$, so on ubiquitin the prediction was 92\% helix while 1UBQ has one helix and five strands. The 1978 breaker rule (stop when the mean propensity of the next tetrapeptide drops below 100) with per-residue $P_\alpha$/$P_\beta$ conflict resolution predicts the 23-34 helix plus strand regions, $Q_3=0.513$ against the literature assignment - the expected range for this method. The parameter table matches the canonical 1978 values for all 20 amino acids. Generated backbones round-trip through a standard parser with consecutive C$\alpha$-C$\alpha$ distances of $3.799$-$3.801$ \AA{}, and restrained refinement lowers the energy from 100.96 to $-8.99$ with exact 3.8 \AA{} bonds.")
o.append(r'\paragraph{(F100) Chou-Fasman nucleation, breaker and conflict rules.} Helix nucleus: $\ge 4$ of 6 residues with $P_\alpha\ge100$; strand nucleus: $\ge 3$ of 5 with $P_\beta\ge100$; extension stops when $\bar P$ over the next tetrapeptide $<100$; overlaps resolved by $\bar P_\alpha$ vs $\bar P_\beta$ over the $\pm3$ window; $Q_3=\frac{1}{n}\sum_i \mathbb{1}[\hat s_i=s_i]=0.513$ on ubiquitin; refinement energy $E=E_{LJ}+E_{elec}+k_b\sum(r-3.80)^2$.')
cg=json.load(open(B+'sweep_chemgpt_engine.json'))
o.append(r'\subsection{Fragment molecule generator against PubChem and live ChEMBL}')
o.append(r"chemgpt\_engine assembles molecules from a 12-fragment library and scores fragment-additive ADMET. Seven assembled molecules - phenol, aniline, benzoic acid, fluorobenzene, 2-aminopyridine, 4-methylimidazole and phenethylamine - each resolved to the correct real compound in PubChem (queried by SMILES), with molecular weights within 0.03 Da. The scoring formulas recompute exactly, and the Pareto front (20 of 24 candidates) matches a brute-force non-dominated filter over an independently regenerated candidate list. Novelty claims were checked against the live ChEMBL similarity service: phenol's nearest neighbor is phenolate sodium at 100\% similarity, while the top generated design has no neighbor at or above 80\%, so its ``novel scaffold'' label is measured, not asserted. No defect was found in this module.")
o.append(r'\paragraph{(F101) Fragment-additive assembly and Pareto filtering.} $MW=\sum_f MW_f-2.016\,(k-1)$ for $k$ fragments; $\log S=0.5-\log P-0.01\,(MW-200)/50$; dominance $a\succeq b\iff \forall j\,o_j^a\ge o_j^b \wedge \exists j\,o_j^a>o_j^b$; Boltzmann weights $w_i=e^{-E_i/0.593}/\sum_j e^{-E_j/0.593}$ sum to 1.')
st=json.load(open(B+'sweep_syn_stab_ai.json'))
o.append(r'\subsection{Circuit stability scorer against recomputation and real restriction sites}')
o.append(r"syn\_stab\_ai estimates the evolutionary stability of synthetic circuits: expression burden, plasmid-loss and mutation survival, a Wright-Fisher-like population simulation and sequence-level risk. All formulas recompute exactly, and the population simulation matches the closed selection recursion in the deterministic limit. Bug 49: the sequence-risk palindrome counter compared each 6-mer with its plain reverse, so real inverted repeats - EcoRI GAATTC, HindIII AAGCTT, SnaBI TACGTA - all counted zero; the reverse-complement check counts them, while textual palindromes such as GATTAG correctly remain at zero. Strategy comparison ranks genomic integration above promoter weakening, consistent with the loss-rate model.")
o.append(r'\paragraph{(F102) Burden, retention and selection recursion.} Burden $b=\min(1,0.25\,g\,e)$; plasmid retention $(1-\lambda)^t$ with $\lambda=\lambda_0(1+4b)$; mutation survival $e^{-\mu\,L\,t}$; update $f\leftarrow f(1-\mu)(1-c)/(1-fc)$ with diffusion noise $\sqrt{f(1-f)/N}$; inverted repeat: $x=\overline{\mathrm{comp}(x)}$.')
ph=json.load(open(B+'sweep_phage_designer.json'))
o.append(r'\subsection{Phage designer against recomputation and adsorption kinetics}')
o.append(r"phage\_designer plans tail-fiber retargeting, chimeric endolysins, adsorption, escape risk and cocktails. The fiber and lysin formulas, escape probability $1-e^{-\mu s N}$ and host-range scoring all recompute exactly. Bug 50: \texttt{adsorption\_kinetics} accepted \texttt{time\_min} but never used it - bound phage was identical at $t=1$ and $t=60$ minutes. Adsorption is a first-order process (Schlesinger 1932), so the function now returns $P_0(1-e^{-kBt})$; post-fix, bound phage grows with time and matches the closed form to machine precision.")
o.append(r'\paragraph{(F103) Fiber adsorption score and first-order kinetics.} Adsorption score $a=\min(0.99,\,0.55+12/K_d)$; lysin potency $\bar\alpha$ with MIC $=\max(0.1,\,8(1.1-\bar\alpha))$ $\mu$g/mL; escape $P=1-e^{-\mu s N}$; kinetics $B(t)=P_0(1-e^{-k\,C\,t})$.')
pf=json.load(open(B+'sweep_phageforge.json'))
o.append(r'\subsection{CRISPR phage forge against the real NDM-1 plasmid and a host-chromosome screen}')
o.append(r"phageforge designs CRISPR-armed phages against resistance genes: backbone selection, guide design, payload budget, kill curves, escape risk and cocktail coverage. On the real blaNDM-1 CDS (813 bp, from plasmid pKpANDM-1, FN396876.1, 4318 bp) the module selects the P1 backbone (15 kb capacity, lytic, the eligible maximum for the 4.5 kb payload) and all three guides verify as 20-mers inside the CDS. Bug 51 couples two defects: the off-target screen ran against the target gene itself while the report claimed a screen against a supplied phage genome - an input that does not exist - and the CFD scanner skipped every perfect-match site, making the worst off-target class invisible (a planted exact match returned zero hits pre-fix). Perfect matches are now reported at CFD 1.0, \texttt{design\_phage} accepts \texttt{background\_genome}, and the report states exactly what was screened; against a real 40 kb window of the K. pneumoniae MGH 78578 chromosome (NC\_009648.1) all three blaNDM-1 guides show zero CFD hits. Bug 52: the cocktail coverage fraction was always 1.0 whenever any host was covered (union denominator); an optional target panel gives a real fraction (0.75 with one uncovered target in the sweep case). Kill curve, escape risk, payload budget and microbiome-sparing recompute exactly; backbone capacities were checked against the NCBI-verified genome sizes (T7 39,937 bp; lambda 48,502; T4 168,903; P1 94,800; M13 6,407) and are payload headroom, plausible but not individually literature-sourced (documented).")
o.append(r'\paragraph{(F104) Phage infection, escape and screening formulas.} Infected fraction $f=1-e^{-a\,\mathrm{MOI}}$; surviving $S=(1-f)(1-r)+r$; effective burst $f\,B$; expected escapees $E=N\mu^{k}$ for $k$ independent targets with $P_{\mathrm{esc}}=1-e^{-E}$; guide off-target risk $R=\sum_{s}\mathrm{CFD}(g,s)$ over background sites within three mismatches, perfect matches included; cocktail coverage $|\mathcal{T}\cap\mathcal{C}|/|\mathcal{T}|$; microbiome sparing $0.6+0.3(1-0.5\,e)$.')
bc=json.load(open(B+'sweep_bio_copilot.json'))
o.append(r'\subsection{Variant copilot against a live ClinVar panel and UniProt}')
o.append(r"bio\_copilot is a variant-interpretation workbench: a mutation-to-phenotype computation graph (variant annotation, structural perturbation, pathway effect, phenotype inference with inconsistency flags), CRISPR guide enumeration, FASTA/PDB structured output, a UniProt-grounded question router, Monte-Carlo uncertainty propagation and beta-binomial experiment feedback. The curated gene slice was checked against live UniProt: all three lengths match exactly (TP53 P04637 393 aa, BRCA1 P38398 1863 aa, KRAS P01116 189 aa) and the TP53 DNA-binding domain 102-292 equals the UniProt feature, while the BRCA1 RING and BRCT windows are wider local approximations (documented against the UniProt zinc finger 24-65 and the BRCT domains 1642-1736 and 1756-1855). An eight-variant panel was scored against live ClinVar records. Bug 53: a premature stop set pathway flux to 1.0, but the risk formula $0.15+0.5f$ capped at 0.65, so TP53 R213* and BRCA1 Q563* - both Pathogenic in ClinVar, one expert-panel reviewed - were returned as ``uncertain significance''. The fix adds a per-gene loss-of-function flag with a PVS1-style floor $r\ge0.75$ (ACMG/AMP guideline, PMID 25741868) and deliberately withholds it from gain-of-function oncogenes: KRAS L168* is Likely benign in ClinVar and other KRAS truncating records are VUS or conflicting, so the module stays in the uncertainty band and raises an explicit caveat flag. Exact-band agreement rose from 4/8 to 6/8; the two remaining calls are one band away with documented rationale (oncogene-nonsense conservatism, and a KRAS hotspot-coverage caveat - the curated hotspot list was not refit to the validation panel). The guide enumerator returns a set identical to crispr\_opt on the real 813 bp blaNDM-1 CDS (137 guides, both strands, same forward-coordinate convention), and to\_pdb output on the real 189-residue KRAS sequence parses cleanly (189 C$\alpha$ atoms, residue names matching, consecutive C$\alpha$-C$\alpha$ $3.8297$ \AA{} against the documented 3.8 \AA{} ideal-helix geometry). Uncertainty propagation matches the analytic product-of-Gaussians mean and the beta-binomial update matches scipy exactly.")
o.append(r'\paragraph{(F105) Variant risk with a mechanism-aware nonsense floor.} $r=0.15+0.5\,f+0.25\,\mathbb{1}_{h}$; flux $f=\min(1,\frac{\Delta\Delta G}{3}\,c)$ with $c=1.5$ at hotspots and $0.8$ otherwise, and $f=1$ for nonsense; $\Delta\Delta G=0.8\,|\Delta H|+1.2\,\mathbb{1}_{h}+0.3\,(1-\mathbb{1}_{h})+0.5\,\mathbb{1}_{d}$ over hydrophobicity change $\Delta H$, hotspot $h$ and domain $d$ indicators; the floor $r\leftarrow\max(r,0.75)$ applies exactly when the variant is nonsense and the gene carries the loss-of-function flag (PVS1-style); bands $r>0.7$ likely pathogenic, $r>0.4$ uncertain, else likely tolerated.')
o.append(r'\paragraph{(F106) Product of independent Gaussians.} $E\big[\prod_{i}X_{i}\big]=\prod_{i}\mu_{i}$ by independence; for $(\mu,\sigma)=(0.8,0.1)$ and $(0.7,0.05)$ the analytic mean is $0.56$, matched by a $2\times10^{4}$-sample Monte-Carlo mean whose 95\% interval contains it.')
o.append(r'\paragraph{(F107) Beta-binomial experimental feedback.} Prior mean $\mu_0$ with strength $s$: $a=\mu_{0}\,s+n_{s}$, $b=(1-\mu_{0})\,s+(n-n_{s})$; posterior mean $a/(a+b)$, equal to the scipy beta mean ($\mu_0=0.5$, $s=10$, $9/10$ successes $\to0.7$).')
bi_=json.load(open(B+'sweep_bioimage_ai.json'))
o.append(r'\subsection{Cell-image analyser against analytic shapes and BBBC001 ground truth}')
o.append(r"bioimage\_ai segments microscopy frames (flat-field correction, Otsu or adaptive threshold, distance-transform splitting), measures per-cell morphology and computes 50 screening diagnostics. Two defects were found on geometric ground truth. Bug 54: the perimeter was the boundary-pixel count, which measures a 45-degree edge at $1/\sqrt2$ of its length - circularity scored 1.27 for a perfect disk and 1.69 for a rotated square. The Freeman chain convention (orthogonal steps $\times1$, diagonal $\times\sqrt2$) gives 0.92 for the disk - the standard region-props value, the residual being pixelation - and exact perimeters for cardinal shapes (76 for a 20-pixel square, $56\sqrt2$ for the diamond). Bug 55: distance-maximum markers fired on mid-ramp pixelation plateaus, so one convex elongated cell was split into three fragments; regional maxima by morphological reconstruction leave a single marker (the same cell now measures aspect 3.74 against nominal 4), while a genuine two-peak touching pair still splits. The Otsu threshold matches an independent between-class implementation exactly, and on all six real BBBC001 images (Broad benchmark, human HT29 cells) the module counts sit 4-9\% above the inter-observer mean and track the manual counts with Pearson $r=0.9983$ - inside the noise band of the two human counters, who disagree by up to 27\% on one image.")
o.append(r'\paragraph{(F108) Otsu thresholding.} Class probabilities $\omega(k)=\sum_{i\le k}p_i$, means $\mu(k)=\sum_{i\le k}i\,p_i$; pick $k^*=\arg\max_k (\mu_T\omega(k)-\mu(k))^2/(\omega(k)(1-\omega(k)))$.')
o.append(r'\paragraph{(F109) Freeman chain perimeter and circularity.} $P=N_{\mathrm{ortho}}+\sqrt2\,N_{\mathrm{diag}}$ over the traced outer boundary chain; circularity $C=4\pi A/P^{2}$; a filled disk scores $\approx0.91$, an $n\times n$ square $4\pi n^{2}/(4(n-1))^{2}$.')
o.append(r'\paragraph{(F110) Regional maxima by reconstruction.} Reconstruct $d-1$ under the mask $d$ by iterated geodesic dilation $r\leftarrow\min(\delta(r),d)$ to stability; maxima $\{d>r\}$; markers label the maxima and each foreground pixel takes its nearest marker (Voronoi split).')
bp_=json.load(open(B+'sweep_bioplayground.json'))
o.append(r'\subsection{Evolution sandbox against population-genetics theory}')
o.append(r"bioplayground simulates a Wright-Fisher construct locus (selection, symmetric mutation, multinomial drift, bottlenecks), directed evolution, Lotka-Volterra competition and diversity metrics. One defect was found. Bug 56: the reported generation count was ten times the number of trajectory snapshots - 310 for a 300-generation run, 100 for a construct lost at generation 92 - and the playground report computed diversity on the last ten-generation snapshot rather than the final state ($h=0.0198$ reported when the construct was already lost, true $h=0$). The fix counts generations directly and exposes the final frequency vector, which the report now uses. Validation is against analytic theory: the two-allele mutation equilibrium $p_t=\frac12+\frac12(1-2\mu)^t$ holds (0.5001 vs 0.5012 at $N=4\times10^4$), a single-species Lotka-Volterra run tracks the closed-form logistic within $8\times10^{-4}$ mid-course and exactly at carrying capacity, coexistence calls match competition theory in both regimes, and the Shannon/heterozygosity metrics equal scipy exactly. A design limitation is documented: the construct starts at frequency 1, so with the default mutation rate every run fixes at generation 1 - loss requires mutation strong enough to seed competing alleles.")
o.append(r'\paragraph{(F111) Selection-mutation recursion and equilibrium.} $p^\prime=p\,w_0/\bar w$ with $\bar w=\sum_i p_i w_i$; symmetric mutation $m_i=s_i(1-\mu)+\mu(1-s_i)/(n-1)$ conserves $\sum_i m_i=1$; two-allele equilibrium $p_t=\frac12+(p_0-\frac12)(1-2\mu)^t$.')
o.append(r'\paragraph{(F112) Logistic competition.} $\dot x_i=g_i x_i(1-\sum_j c_{ij}x_j)$; single-species solution $x(t)=K/(1+A e^{-gt})$, $A=K/x_0-1$, $K=1/c$; coexistence requires interspecific competition below intraspecific for both species.')
o.append(r'\paragraph{(F113) Diversity metrics.} Heterozygosity $h=1-\sum_i x_i^2$; Shannon $H=-\sum_i x_i\ln x_i$; effective alleles $e^{H}$.')
bpr=json.load(open(B+'sweep_bioprint_pro.json'))
o.append(r'\subsection{Bioprint multiphysics against constitutive-equation ground truth}')
o.append(r"bioprint\_pro calibrates bioinks (Cross-model rheology, Hagen-Poiseuille pressure, first-order crosslinking) and runs a multiphysics chain: extrusion, reaction-diffusion gelation, poro-viscoelastic mechanics and a maturation ODE, with 51 computed diagnostics and a seeded global optimizer. Two defects were found. Bug 57: the extrusion flow used the viscosity at a guessed shear (6.7 s$^{-1}$) while the resulting wall shear was 33.9 s$^{-1}$; the shear-thinning ink is far thinner there, so the flow rate came out 4.36$\times$ low (0.213 vs 0.928 mm$^3$/s). The fixed point of $q=\pi r^4\Delta p/(8\,\eta(4q/\pi r^3)\,L)$ is now solved by bisection and matches an independent root finder. Bug 58: the stress model was labeled Oldroyd-B while returning a shear-thinning stress; an Oldroyd-B fluid has constant shear viscosity, so the label now reads Giesekus-family. The calibrator recomputes exactly for all 15 windows (alginate at 8 mm/s: 160 s$^{-1}$, 6.512 Pa$\cdot$s, 104.2 kPa), the gelation PDE matches $1-e^{-kt}$ at the surface, and the maturation ODE matches an independent RK4 integration to $10^{-7}$.")
o.append(r'\paragraph{(F114) Cross/Carreau rheology and pipe flow.} Cross: $\eta=\eta_\infty+(\eta_0-\eta_\infty)/(1+(\lambda\dot\gamma)^n)$; Carreau-Yasuda: $\eta_\infty+(\eta_0-\eta_\infty)(1+(\lambda\dot\gamma)^a)^{(n-1)/a}$; wall shear $\dot\gamma_w=4Q/\pi r^3$; self-consistent rate $Q=\pi r^4\Delta p/(8\,\eta(\dot\gamma_w)\,L)$.')
o.append(r'\paragraph{(F115) Gelation, relaxation and maturation.} Conversion $x=1-e^{-kt}$, $t_{95}=-\ln0.05/k$; modulus $E_0(1+9x)$; stiffness $2+48\,g^2$ kPa; standard-solid strain $\epsilon(\tau)=\epsilon_0(0.35+0.65e^{-t/\tau})$; Euler buckling $E\pi^2/(12n^2)$; maturation $\dot c=0.18\,c(1-c/5)\,o-0.03c$ with oxygen $\dot o=0.25(1-o)-0.08\,c\,o$.')
bsv=json.load(open(B+'sweep_biosimvr.json'))
o.append(r'\subsection{Virtual-lab sessions and mechanistic experiments}')
o.append(r"biosim\_vr pairs a scripted virtual bench (move, pipette, incubate, measure) with mechanistic experiments: rigid-pose Lennard-Jones docking by differential evolution, CRISPR guide enumeration, and a stochastic protocol simulator with 51 asserted diagnostics. Two defects were found and fixed. Bug 59: the scripted transfection session set the plate signal to 0.72 but measured the plate-reader object, which has no signal state, so the log read 0.0 while the conclusion claimed 0.72 RFU; the measurement now targets the plate. Bug 60: the docking session crashed outright, calling \texttt{dock} with swapped arguments and a nonexistent \texttt{seed} keyword; it now reports $-2.94$ kcal/mol. The guide enumerator reproduces crispr\_opt's forward-strand set exactly on the real \emph{bla}$_{\mathrm{NDM\text{-}1}}$ CDS (65 guides), the rotation is a proper rotation, the returned docked pose reproduces the returned score exactly with rigid bonds, and on a spherical ground-truth pocket the ligand settles at the LJ well (3.00 \AA).")
o.append(r'\paragraph{(F116) Virtual-lab kinetics and scoring.} Incubation gain $g=(1-e^{-t/240})\,e^{-((T-37)/12)^2}$; shifted LJ well $u(r)=(3/r)^{12}-2(3/r)^{6}$ with minimum $-1$ at $r=3$; guide score $\max(0,\,1-2|\mathrm{GC}-0.5|-0.15\max(0,h-3))/(1+n_{\mathrm{dup}})$.')
ctw=json.load(open(B+'sweep_cell_twin.json'))
o.append(r'\subsection{Digital cell twins and virtual drug trials}')
o.append(r"cell\_twin builds a multi-omic patient-cell state and screens drug responses with a viable/apoptotic/proliferating/damage ODE. Two defects were found and fixed. Bug 61: the reported maximum apoptosis was taken at the last-listed dose, so a descending dose list silently returned the minimum-dose value. Bug 62: the combination screen claimed a mechanistic combined-exposure rerun but merely added a constant $+0.08$ synergy bonus to the Bliss expectation for every pair; combinations are now genuinely rerun with the Bliss-combined effect scalar $1-(1-e_a)(1-e_b)$ in the response ODEs, so the Bliss excess is solved, not assumed. The pathway activities $s/(s+100)$, the effect scalar $k\cdot d/(d+1)\cdot(1-r)$, and the Bliss expectation all recompute exactly, and the single-drug ODE matches an independent RK4 integration to $10^{-3}$ in terminal viability.")
o.append(r'\paragraph{(F117) Twin response model.} Pathway activity $A=s/(s+100)$; effect $e=k\,d/(d+1)\,(1-r)$; ODE $\dot v=g-d_{\mathrm{kill}}$, $\dot a=d_{\mathrm{kill}}-0.02a$, $\dot p=-0.05ep+0.02A_p(1-p)$, $\dot u=i-0.03A_{\mathrm{rep}}u-0.02u$ with $g=0.04A_pv(1-v/2)$, $i=0.08ev$, $d_{\mathrm{kill}}=i(0.5+A_a)(1-0.5A_s)$; Bliss combination $e_{ab}=1-(1-e_a)(1-e_b)$.')
o.append(r"\subsection{Module 91: cellpainter (Cell Painting morphological profiling)}")
o.append(r"\paragraph{Finding (BUG 63).} Mechanism similarity was cosine over raw signature vectors whose entries sit near 1.0 (fold change vs vehicle), so the shared baseline dominated: distinct mechanisms scored about 0.999 (sugarcode-ai commit e6fb780) and the novel-mechanism hint could never trigger. After the fix, similarity is computed on vehicle-subtracted deltas: the three distinct mechanism pairs score 0.0, the same mechanism at two doses scores 1.0, and the novel-mechanism hint is reachable (benchmarks/sweep\_cellpainter.json, 6/6 checks passed). The image path on real BBBC001 stacks is deferred to cellpainter\_4d.")
o.append(r"\paragraph{(F118) Delta-cosine and signature model.} Signature feature $s_j=1+(\delta_j-1)\log_{10}(1+d)\min(1,h/24)$ for dose $d$ and time $h$; similarity $\cos(\mathbf{s}_a-\mathbf{1},\mathbf{s}_b-\mathbf{1})$; plate normalisation $z=(x-\tilde{x})/(1.4826\,\mathrm{MAD})$; vehicle ($d=0$) gives $\mathbf{s}=\mathbf{1}$ exactly. Recomputed signature value 1.12 matched the module; QC CV 0.0816 matched.")
o.append(r"\subsection{Module 92: cellpainter\_4d (temporal morphology and real nuclear images)}")
o.append(r"\paragraph{Finding (BUG 64).} The morphology rate constant was set from the observation window ($\tau=T_{\mathrm{obs}}/5$) while cell death used fixed hourly rates, so the same apoptosis run gave 12 h nuclear areas of 71.49, 120.84 and 152.29 $\mu\mathrm{m}^2$ for 24, 72 and 144 h windows. Kinetics now use a fixed program clock and the 12 h area is 120.84 for every window (benchmarks/sweep\_cellpainter\_4d.json).")
o.append(r"\paragraph{Real images.} New segment\_nuclei on BBBC001 (6 HT29 Hoechst fields, two human counters): mean count deviation 8.18\% (inter-human 11\%, CellProfiler 6.2\%). Negative result: two earlier drafts scored 7.0\% and 5.8\% but leaked across the watershed background (synthetic 121-px disks measured 145/109/109, then 81 px); the shipped version is the geometry-correct one and nothing was tuned to the ground truth.")
o.append(r"\paragraph{(F119) Program-clock relaxation and segmentation geometry.} $a(t)=a_0t_a+a_0(1-t_a)e^{-t/\tau}$, $\tau=T_{\mathrm{prog}}/(5s)$; $n(t)=n_0e^{-0.04t}$ (apoptosis); Otsu $t^\ast=\arg\max_t\,[\mu_T\omega(t)-\mu(t)]^2/[\omega(t)(1-\omega(t))]$; seed radius $r=\tfrac12\sqrt{\tilde{A}/\pi}$; circularity $4\pi A/P^2$ with $P=\tfrac{\pi}{4}E$ for $E$ exposed pixel edges; aspect ratio $\sqrt{\lambda_1/\lambda_2}$ of the pixel covariance.")
o.append(r"\subsection{Module 93: crispr\_cargo (delivery vehicle selection and PK)}")
o.append(r"\paragraph{Finding (BUG 65).} pk\_model added a zero-width-time trapezoid $(c_0+c_0)/2\cdot dt$ at $t=0$, overstating AUC by exactly $c_0\,dt$ at every step size: $+5.8\%$ for LNP over 96 h at $dt=1$ (608.317 vs analytic 574.824). The fixed grid matches the closed form $C_0/k_e(1-e^{-k_e t})$ to $2.8\times10^{-4}$ relative at $dt=1$ and exactly at $dt=0.01$ (benchmarks/sweep\_crispr\_cargo.json).")
o.append(r"\paragraph{(F120) One-compartment PK and payload accounting.} $C(t)=(D/V_d)e^{-k_e t}$, $k_e=\ln2/t_{1/2}$; $\mathrm{AUC}=C_0(1-e^{-k_e T})/k_e$; CDS length $=3N_{aa}+3$ bp (UniProt Q99ZW2 SpCas9 1368 aa $\to$ 4107 bp, J7RUA5 SaCas9 1053 aa $\to$ 3162 bp, fetched live); AAV's 4.7 kb cargo limit leaves under 0.6 kb once the SpCas9 CDS is in. Compartment mass balance error $<10^{-6}$.")
o.append(r"\subsection{Module 94: crispr\_muse (adaptive guide design)}")
o.append(r"\paragraph{Finding (BUG 66).} enumerate\_configurations only searched 3$'$ of the spacer for the PAM, but Cas12a (TTTV) and CasX (TTCN) PAMs are 5$'$ of the spacer, so every valid Cas12a/CasX site was missed (0 configurations on a 5$'$-TTTA + 23-nt guide construct). A pam\_side field fixes this; Cas9 enumeration is unchanged (benchmarks/sweep\_crispr\_muse.json).")
o.append(r"\paragraph{(F121) Posterior and policy quantities.} Beta posterior $\alpha'=a+s$, $\beta'=b+f$, $\mu=\alpha'/(\alpha'+\beta')$, $\sigma^2=\alpha'\beta'/[(\alpha'+\beta')^2(\alpha'+\beta'+1)]$ (matches Beta(9,3): 0.75, 0.1201); clonal selection $f_i^{t+1}=f_i^t w_i/\sum_j f_j^t w_j$ (b after 10 doublings: $102.4/103.3$); policy entropy $-\sum p\ln p$, uniform $=\ln 4$; repair prior $[1.1-0.35m,\;0.2+1.5m,\;0.05+1.4\,d\,s]$ with microhomology $m$, donor $d$, S-phase $s$.")
open('sections_results4.tex','w').write('\n'.join(o)+'\n')
